(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-asr-keyword-bifocal"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-1\">一 · 一次漏检如何把整条链路拖垮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-2\">二 · 它到底在省什么：算力与带宽的双重浪费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-3\">三 · 机制拆解：判断、裁剪、精细解码、拼接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-4\">四 · 适用边界：什么时候该退回全量解码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-5\">五 · 稳定性技巧与三个必须防的失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-6\">六 · 关键词聚焦 ASR 的失效边界：漏检、错位与收益反转</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-7\">七 · 帧流入栈：KWS 分支的输入、输出与常驻代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-8\">八 · 调度器裁剪：窗口生成、批混合与调度开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-9\">九 · 主 ASR 精细解码：裁剪窗口内的声学编码与解码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-10\">十 · 非关键词帧的廉价路径：低精度、低帧率与状态保持</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-11\">十一 · 拼接与下游交接：结果组装、时间戳对齐与漏检兜底</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-12\">十二 · 按场景切换：$\\rho$ 的在线估计与路径选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-13\">十三 · 边界条件：ρ、漏检率与窗口错位三者共同决定是否该启用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-14\">十四 · 主公式的逐项拆解与 ρ 的物理含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-15\">十五 · 窗口裁剪的几何推导与错位代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-16\">十六 · 伪代码：从帧流到拼接结果</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-17\">十七 · 系统代价：带宽、显存与批内碎片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-18\">十八 · 一个具体例子：命令词请求的端到端账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-19\">十九 · 推导的边界：何时公式失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-20\">二十 · 裁剪窗口的收益边界与漏检代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-21\">二十一 · 请求形态决定 ρ 的分布，而不是平均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-22\">二十二 · 长度分布与裁剪窗口的批内对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-23\">二十三 · 并发与批大小的配方边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-24\">二十四 · 负载不对时的三种塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-25\">二十五 · 配方与部署形态的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-26\">二十六 · 关键词聚焦 ASR 的负载配方与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-27\">二十七 · 硬件档位与分支放置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-28\">二十八 · 并行拓扑：窗口批而非帧批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-29\">二十九 · 量化方案：按分支分治</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-30\">三十 · KV 策略：窗口局部缓存与上下文状态分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-31\">三十一 · 调度参数与漏检兜底</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-32\">三十二 · 可复现配置思路与场景切换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-33\">三十三 · 关键词聚焦 ASR 的部署边界：配方在什么条件下失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-34\">三十四 · 裁剪窗口把算力账单改写成带宽账单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-35\">三十五 · 共享前端缓存决定了通信与重复计算的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-36\">三十六 · 尾延迟：漏检回退是唯一的硬尾巴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-37\">三十七 · 功耗与规模：先崩的是调度器而不是张量核</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-38\">三十八 · 场景切换逻辑本身就是一笔吞吐税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-39\">三十九 · 裁剪窗口调度先撞上的不是算力，是带宽与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-40\">四十 · 漏检链路的可观测化：从召回缺口到帧级归因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-41\">四十一 · 特征缓存不一致与窗口错位的静默故障</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-42\">四十二 · OOM 与批抖动的耦合：裁剪窗口批的碎片化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-43\">四十三 · 路由不均与场景切换的迟滞</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-44\">四十四 · 尾延迟尖刺的定位与回滚策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-45\">四十五 · 关键词聚焦 ASR 的失效边界与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-46\">四十六 · 决策维度：把选型压缩成三个可测量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-47\">四十七 · 决策表：五条路径的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-48\">四十八 · 适用条件的量化边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-49\">四十九 · 与全量解码的切换逻辑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-50\">五十 · 与量化、分块、批调度的组合判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-51\">五十一 · 选型失败的反向信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-keyword-bifocal-sec-52\">五十二 · 关键词聚焦 ASR 的选型边界：与全量解码、级联 KWS-ASR 的分野</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">流式音频帧先进入轻量 KWS 分支，输出关键词候选与时间戳</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器据关键词位置裁剪主 ASR 的输入帧窗口</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">主 ASR 对裁剪窗口做精细声学编码与解码，得到关键词文本</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">非关键词帧走低精度/低帧率路径，仅保留上下文状态</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">结果拼接后送入下游 NLU，KWS 与 ASR 共享前端特征缓存</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-asr-keyword-bifocal-sec-1\">一 · 一次漏检如何把整条链路拖垮</h3>\n<p>设想一个已经上线的语音助手推理栈：流式前端每 20 ms 吐一帧特征，KWS 分支常驻，命中关键词就把时间戳交给调度器，主 ASR 只对裁剪窗口做精细解码。某个早高峰，机房一侧的噪声底噪抬高，一批带口音的“打开空调”请求里，KWS 的置信度掉到阈值以下，候选没有被输出。调度器于是认为这段 utterance 不含关键词，主 ASR 对这些帧全部走低精度、低帧率路径，只保留上下文状态，不做精细声学编码。下游 NLU 收到的是一段几乎空白的文本，用户侧表现为“喊了三遍没反应”。</p>\n<p>这起事故的要害不在 KWS 本身不够准，而在于系统的计算分配被一个二值判断绑死了：KWS 命中则主模型精细解码，未命中则主模型近乎放弃。全量解码路径下，同样的噪声与口音只会让识别结果变差一点，词仍然出得来；聚焦路径下，判断错误直接把“差一点”放大成“完全没有”。这就是关键词聚焦 ASR 必须被单独讨论的原因——它用一次前置判断换掉了主模型对全部帧的一视同仁，收益与风险来自同一个开关。</p>\n<p>从系统代价看，事故的代价是召回率而非延迟：首包延迟因为 KWS 常驻前端反而更低，但关键词召回塌陷，等于把 SLO 里最硬的那条指标打穿。工程上这类故障最难排查，因为监控面板上 GPU 利用率、批大小、首包 P99 全都好看，只有下游 NLU 的意图命中率在掉。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-2\">二 · 它到底在省什么：算力与带宽的双重浪费</h3>\n<p>语音助手的流量构成决定了全量解码的浪费形态。多数请求是“设个闹钟”“下一首”“音量加三”这类短命令，utterance 里真正需要精细识别的只有中间那一小段，前后是静音、呼吸、环境噪声和礼貌用语。全量 ASR 却对每一帧都做完整的声学编码与自回归解码，消耗的是算力，也是显存带宽——解码器每一步都要读权重、读 KV cache，帧数与这些读取次数成正比。</p>\n<p>聚焦方法把计算量重新分配，节省比例可以写成关键词时长占 utterance 的比例：</p>\n<div class=\"formula\">$$\\text{FLOPs}_{\\text{bifocal}} \\approx \\text{FLOPs}_{\\text{KWS}} + \\rho \\cdot \\text{FLOPs}_{\\text{ASR}},\\quad \\rho = \\frac{T_{\\text{kw}}}{T_{\\text{utt}}} \\ll 1$$</div>\n<p>KWS 分支的 FLOPs 相对主模型可以忽略，于是总算力近似按 ρ 缩放。ρ 越小，节省越多。一条 3 秒的“把客厅灯调暗一点”，关键词窗口可能只覆盖几百毫秒，ρ 落在很小的量级，主 ASR 的精细计算被压缩到原来的一个零头；反过来，一段自由听写的会议记录里几乎每帧都承载语义，ρ 接近 1，公式退化为全量解码加一份 KWS 开销，净收益为负。</p>\n<p>这里要区分两种代价。算力节省体现在吞吐上：同样一张卡，裁剪窗口让主 ASR 的批里塞进更多请求，因为每个请求贡献的帧数变少。带宽节省体现在非关键词帧走低精度或低帧率路径，KV cache 的写入与读取量随之下降。但调度器本身要维护窗口边界、拼接结果、处理跨请求的窗口混合批，这部分开销是固定的，ρ 大时它会反过来吃掉收益。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-3\">三 · 机制拆解：判断、裁剪、精细解码、拼接</h3>\n<p>按帧流顺序，链路是四段。第一段，流式音频帧进入轻量 KWS 分支，输出关键词候选与时间戳；KWS 与主 ASR 共享前端特征缓存，避免同一段音频被提取两次，这是部署配方里最容易被忽略却最影响带宽的一条。第二段，调度器依据关键词位置裁剪主 ASR 的输入帧窗口，窗口通常带一点前后余量，防止边界音素被截断。第三段，主 ASR 只对裁剪窗口做精细声学编码与解码，得到关键词文本；非关键词帧 meanwhile 走低精度或低帧率路径，仅保留上下文状态供后续窗口衔接。第四段，结果拼接后送入下游 NLU。</p>\n<p>伪代码层面，调度器的核心是一个窗口队列：</p>\n<ul>\n<li>对每个流式请求维护 <em>pending_frames</em> 与 <em>context_state</em>；</li>\n<li>KWS 输出 (keyword, t_start, t_end) 时，把 [t_start−δ, t_end+δ] 压入精细窗口队列；</li>\n<li>批调度按窗口长度而非整条 utterance 组批，不同请求的裁剪窗口可以混在同一批里；</li>\n<li>窗口之间用 <em>context_state</em> 衔接，保证声学上下文不断裂；</li>\n<li>若某请求在超时内没有任何 KWS 候选，触发兜底：回退全量解码。</li>\n</ul>\n<p>这套机制对显存的影响是双向的。裁剪窗口缩短了单请求的解码步数，KV cache 占用下降；但为了支持窗口混合批与上下文衔接，调度器需要保留每个请求的 <em>context_state</em>，这部分常驻显存不随 ρ 缩小。批量增大时，窗口边界对齐带来的 padding 浪费会成为新的带宽开销，窗口越短、批越碎，这个比例越高。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-4\">四 · 适用边界：什么时候该退回全量解码</h3>\n<p>适用面很窄但很值钱：关键词与命令词占比高、utterance 中关键词稀疏的助手场景。判断是否启用，看的是流量构成而不是单条请求。运维上可以按 KWS 候选密度做在线统计——单位时间内的候选数与总帧数之比，密度低说明 ρ 小，聚焦路径划算；密度高说明流量正在向自由听写漂移，应切回全量解码。</p>\n<p>不解决的问题要列清楚。第一，它不提升单帧识别精度，主 ASR 在裁剪窗口内的声学建模与全量路径完全一致，噪声与口音带来的错误率不会因为聚焦而下降。第二，它不解决远场拾音、回声消除、说话人分离这些前端问题，KWS 在噪声下漏检恰恰是前端质量的下游表现。第三，它不适用于关键词密集或连续语音输入，ρ 接近 1 时裁剪调度开销反成负担，吞吐低于全量解码。第四，它不改变解码器本身的数值精度策略，量化仍按分支分别配置——KWS 可用更激进的低比特，主 ASR 保留精细路径。</p>\n<p>规模上限由两个因素约束：KWS 召回率决定漏检风险的上界，裁剪窗口调度开销决定批处理的效率下界。召回率不够高时，兜底策略（漏检回退全量解码）会被频繁触发，等于每条请求都跑两遍，吞吐反而崩。所以上线前必须把兜底触发率当作一等指标监控，而不是只看平均 ρ。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-5\">五 · 稳定性技巧与三个必须防的失败模式</h3>\n<p>第一个失败模式是漏检，噪声与口音下更易发生，后果是关键词未被精细解码、召回率下降。对策是兜底：KWS 无候选但音频能量或时长超过阈值时，强制走全量解码；兜底率本身要设上限告警。第二个失败模式是场景漂移，自由听写流量混入助手入口，ρ 抬升，裁剪收益消失而调度开销仍在，表现为吞吐低于全量解码。对策是按流量构成动态启用，用候选密度做切换判据，而不是按产品线静态配置。</p>\n<p>第三个失败模式最隐蔽：KWS 与主 ASR 前端特征缓存不一致，或时间戳偏移，导致裁剪窗口错位，关键词被截断解码。这类错误不会让文本为空，而是让文本“差一个字”，比如“打开空调”变成“打开空”，下游 NLU 匹配失败但日志里看不出异常。对策是共享同一份前端特征缓存、统一时间戳基准，并在窗口两端留固定余量；上线前用对齐探针验证 KWS 时间戳与主 ASR 帧索引的偏移是否为零。</p>\n<p>从容量规划角度，聚焦路径的容量模型要按两套参数算：关键词请求按 ρ 缩放后的主 ASR 帧数估吞吐，兜底请求按全量帧数估，两者加权得到实际容量。若只按平均 ρ 估算，兜底率一升高就会打穿 SLO。首包延迟主要由 KWS 常驻前端决定，与批大小弱相关；尾延迟则由兜底请求的全量解码主导，这两条曲线要分开画。</p>\n<p>最终落到一个工程判断上：关键词聚焦 ASR 不是把 ASR 变准的方法，而是把算力从“不需要精细识别的帧”搬到“需要精细识别的帧”的调度方法。它的正确性完全依赖 KWS 判断与窗口对齐这两件事，任何一件失守，收益立刻变成召回事故。因此启用它的前提不是模型能力，而是兜底路径、对齐探针与流量构成监控三件基础设施同时到位。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-6\">六 · 关键词聚焦 ASR 的失效边界：漏检、错位与收益反转</h3>\n<p>这套方案真正解决的问题只有一个：语音助手里“全量解码”的算力错配。线上事故的典型形态是——早高峰时段命令词请求占比高，主 ASR 仍对整段 utterance 做逐帧精细声学编码，显存带宽与 tensor core 被大量静音帧和无关语音吃掉，首包延迟在队列里被放大，SLO 打穿。KWS 分支常驻流式前端、按时间戳裁剪主 ASR 输入窗口后，主模型算力集中到关键词窗口，非关键词帧走低精度或低帧率路径只保留上下文状态，计算量按 <span class=\"formula\">$$\\mathrm{FLOPs}_{\\mathrm{focus}} \\approx \\rho\\cdot \\mathrm{FLOPs}_{\\mathrm{full}}$$</span> 收缩，$\\rho$ 为关键词时长占 utterance 比例。它不解决自由听写、长语音转写、关键词密集场景的吞吐问题，也不改善主 ASR 本身的声学建模精度——裁剪窗口内的精细解码质量与全量路径一致，收益全部来自“少算无关帧”。</p>\n<p>边界首先由 KWS 召回率划定。漏检意味着关键词从未进入精细解码窗口，输出直接缺失该词，召回率下降；噪声与口音环境下漏检概率上升，且漏检是静默失败，下游 NLU 拿到的是残缺文本而非错误码。工程上必须配置漏检回退：KWS 置信度低于阈值或窗口内声学置信度异常时，该请求退回全量解码路径，代价是这部分流量重新吃掉全量算力，容量规划要按“回退比例 × 全量成本”预留余量。第二类失效是时间戳错位：KWS 与主 ASR 若前端特征缓存不一致或时间戳偏移，裁剪窗口会截断关键词首尾音素，解码出半截词，这类错误比漏检更难排查，因为文本看似合法。共享前端特征缓存因此不是优化项而是正确性前提。</p>\n<p>收益反转发生在 $\\rho$ 接近 1 时。自由听写场景关键词占比接近全部帧，裁剪窗口几乎覆盖整段音频，调度器的窗口切分、批内不同窗口的拼接与结果合并开销反而叠加在全量解码之上，吞吐低于直接全量路径。此时正确动作是按流量构成动态切换：命令词请求走聚焦路径并按裁剪窗口混合批处理，自由听写请求走全量解码批，两条路径共享前端但独立配置量化精度——KWS 分支可用更激进精度常驻，主 ASR 保留精细路径。规模上限由此受两个量约束：KWS 召回率决定可承受的回退比例，裁剪窗口调度开销决定批处理的经济批大小；任一越界，召回与吞吐双输。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统表现</th><th>工程对策</th></tr></thead><tbody><tr><td>KWS 漏检（噪声/口音）</td><td>关键词缺失，召回率下降，静默失败</td><td>置信度阈值回退全量解码，预留回退算力</td></tr><tr><td>特征缓存/时间戳错位</td><td>窗口截断，解码出半截词</td><td>KWS 与主 ASR 共享前端特征缓存</td></tr><tr><td>$\\rho \\to 1$（自由听写）</td><td>裁剪收益消失，调度拼接开销反超</td><td>按流量构成切换全量解码路径</td></tr></tbody></table>\n<h3 id=\"alg-asr-keyword-bifocal-sec-7\">七 · 帧流入栈：KWS 分支的输入、输出与常驻代价</h3>\n<p>按请求在时间轴上的流动顺序拆解，第一步永远是音频帧进入流式前端。输入是固定帧率（典型 10–20 ms 一帧）的 PCM 或已做前端特征提取的帧块，输出是 KWS 分支给出的关键词候选集合与每个候选的起止时间戳。这一步的关键工程约束是：KWS 必须常驻流式前端，不能按请求启停，因为它的输出决定了后续主 ASR 的输入窗口，属于控制面而非数据面。常驻意味着它的权重与激活必须小到能与前端特征提取共享同一块显存预算，否则每个并发请求都多一份常驻开销，显存带宽被无谓占用。</p>\n<p>代价集中在两个方向。其一是首包延迟：KWS 分支的推理延迟直接叠加在整条链路最前端，任何后续裁剪都救不回来，因此它的算子应尽量走低精度、低帧率路径，把单帧计算压到可忽略量级。其二是误检与漏检的分布，KWS 输出的是候选而非判决，候选过多会让调度器裁剪出过多窗口，主 ASR 的批处理被碎片化；候选过少则漏检。用伪代码表达这一步的契约：</p>\n<div class=\"formula\">$$\\text{KWS}: \\{x_t\\}_{t=1}^{T} \\rightarrow \\{(\\text{kw}_i, s_i, e_i)\\}_{i=1}^{K},\\quad \\text{recall}_{\\text{KWS}} \\ge \\tau$$</div>\n<p>其中 $\\tau$ 是调度器愿意接受的最低召回阈值，它决定了后面兜底策略的触发频率。具体例子：一个 3 秒的“打开客厅灯”请求，KWS 在 0.4–1.1 s 区间给出候选“客厅灯”，时间戳精度直接决定裁剪窗口是否包含完整词边界；若时间戳偏移半个词，主 ASR 拿到的是被截断的声学片段，解码结果退化为无意义音节。这一步的系统代价是显存常驻 + 每帧固定算力，吞吐上表现为并发上限被常驻分支占用一部分 SM 与带宽。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-8\">八 · 调度器裁剪：窗口生成、批混合与调度开销</h3>\n<p>第二步是调度器把 KWS 的时间戳翻译成主 ASR 的输入帧窗口。输入是候选时间戳、请求的流式缓冲状态、以及当前批内其他请求的窗口；输出是一组待精细解码的帧区间，以及每个区间对应的上下文状态句柄。这里有两个必须显式处理的机制。第一是窗口扩展：时间戳来自 KWS 的帧级判决，边界不可靠，工程上要在候选两侧各扩若干帧作为保护带，代价是 $\\rho$ 被抬高，节省比例下降。第二是批混合：不同请求的裁剪窗口长度不一，调度器要把它们拼成定长 batch，短窗口填充、长窗口切分，填充比例直接吃掉吞吐收益。</p>\n<p>裁剪带来的调度开销是本方法最容易被低估的代价。全量解码时批处理是规整的等长序列，裁剪后每个请求的窗口位置、长度、上下文句柄都不同，调度器每步都要做窗口对齐与状态索引，这部分 CPU 侧开销在关键词极短（$\\rho$ 很小）时会反超节省下来的 GPU 算力。用公式刻画净收益：</p>\n<div class=\"formula\">$$\\text{speedup} \\approx \\frac{1}{\\rho + \\dfrac{c_{\\text{sched}}}{\\text{FLOPs}_{\\text{full}}}}$$</div>\n<p>其中 $c_{\\text{sched}}$ 是单位请求的调度与拼接开销。$\\rho$ 越小，分母第二项越不可忽略，收益被调度开销侵蚀。具体例子：一批 32 个请求，其中 28 个是单词命令词、4 个是较长口述，调度器若按最长窗口对齐整批，则短请求被填充到长窗口长度，实际 $\\rho$ 被拉高到接近批内最大值，节省失效；正确做法是按窗口长度分桶，把短命令词请求聚成一批，代价是批内请求数下降、GPU 利用率波动。这一步的显存代价体现在 KV 状态的管理：非关键词帧仍需保留上下文状态句柄，窗口裁剪不等于状态裁剪。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-9\">九 · 主 ASR 精细解码：裁剪窗口内的声学编码与解码</h3>\n<p>第三步是主 ASR 对裁剪窗口做精细声学编码与解码。输入是窗口内的帧块加上从共享前端缓存取来的上下文特征；输出是关键词文本 token 序列。这一步的机制要点是：主 ASR 并不重新做前端特征提取，而是复用 KWS 已经算过的特征缓存，只对窗口内的帧做编码器前向与自回归（或非自回归）解码。复用缓存是省带宽的关键——前端特征提取的算力在整条链路中占比不低，重复提取会让裁剪省下的算力被抵消。</p>\n<p>代价分布在这一步最集中。编码器前向的算力与窗口长度成正比，解码步数与输出 token 数成正比；由于窗口短，解码的批内并行度低，单请求的解码延迟反而可能比全量解码更高（固定开销摊不开）。这是裁剪方法的固有矛盾：总算力下降，但单请求关键路径上的固定开销占比上升。具体例子：一个 200 ms 的命令词窗口，编码器只需处理十余帧，但解码器的首步固定开销（状态初始化、KV 分配）与全量解码相同，导致该请求的尾延迟不降反升。工程上的应对是把多个请求的裁剪窗口拼成一个大 batch 一起解码，用批内并行摊薄固定开销，代价是批内最长窗口决定整批延迟，短请求被长请求拖尾。</p>\n<p>数值精度上，主 ASR 保留精细路径，与 KWS 分支的激进低精度形成分层：KWS 可以用更低位宽换取常驻成本下降，主 ASR 的窗口解码必须维持足够精度以保证关键词文本正确，因为下游 NLU 对命令词的字符级错误极其敏感。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-10\">十 · 非关键词帧的廉价路径：低精度、低帧率与状态保持</h3>\n<p>第四步处理窗口之外的帧。输入是未被裁剪进主 ASR 窗口的帧；输出不是文本，而是被压缩后的上下文状态，供后续窗口解码时接续。机制上有两条可选路径：低精度路径（用更低位宽跑同一编码器，只更新状态不做解码）与低帧率路径（抽帧或跳帧，仅保留足以维持上下文连续性的状态更新）。两条路径的共同目标是省显存带宽而非省算力——非关键词帧的数量占大头，它们的特征读写是带宽的主要消耗者。</p>\n<p>这一步的工程判断在于状态保真的边界。上下文状态若被过度压缩，后续窗口解码会丢失前文语境，表现为代词消解、跨词边界连读的错误。代价可以定性为：廉价路径的带宽节省与状态失真带来的召回损失之间的权衡，且失真在长请求上累积。具体例子：一段 10 秒的连续语音中只有末尾 1 秒含命令词，前 9 秒走低帧率路径，若抽帧过狠，窗口解码时编码器缺少足够的左侧上下文，命令词的首音素被误判。因此廉价路径的抽帧率必须与主 ASR 的感受野匹配，而不是任意压低。</p>\n<p>这一步还承担一个隐性职责：它是漏检兜底的观测点。若廉价路径的状态更新中出现高能量或高似然的关键词迹象，可作为回退全量解码的触发信号，把 KWS 漏检的损失在链路中段挽回一部分。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-11\">十一 · 拼接与下游交接：结果组装、时间戳对齐与漏检兜底</h3>\n<p>第五步把窗口解码出的关键词文本与非关键词帧的状态拼接成完整结果，送入下游 NLU。输入是关键词文本、其时间戳、以及整条请求的状态序列；输出是结构化识别结果。拼接不是字符串连接那么简单：关键词文本需要按时间戳插回原时间轴，非关键词帧若走了廉价路径则没有对应文本，结果中呈现为空白或占位，下游 NLU 必须能处理这种稀疏文本形态。这一步的机制核心是时间戳对齐的一致性——KWS 的时间戳与主 ASR 解码出的词边界若来自不同时钟基准，拼接会错位。</p>\n<p>兜底策略在这一步落地。触发条件包括：KWS 候选为空但廉价路径观测到可疑信号、窗口解码置信度低于阈值、或拼接后结果与请求类型不匹配。触发后回退到全量解码，代价是该请求的延迟翻倍且占用全量算力，但避免了召回损失。用条件期望刻画整体召回：</p>\n<div class=\"formula\">$$\\text{Recall} = \\text{recall}_{\\text{KWS}}\\cdot \\text{recall}_{\\text{win}} + (1-\\text{recall}_{\\text{KWS}})\\cdot \\text{recall}_{\\text{fallback}}$$</div>\n<p>具体例子：噪声环境下 KWS 漏检“关灯”，廉价路径观测到短时高能量段触发兜底，全量解码补回该命令，代价是这条请求的尾延迟显著高于同批其他请求，调度器需要为兜底请求预留算力余量，否则兜底会挤占正常请求的批处理空间。这一步的系统代价是尾延迟分布变厚，容量规划必须按兜底触发率而非平均值来配置。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-12\">十二 · 按场景切换：$\\rho$ 的在线估计与路径选择</h3>\n<p>最后一步是运行时的路径选择，它不是请求内的步骤，而是跨请求的控制环。输入是近期流量的关键词占比估计与兜底触发率；输出是当前批次走裁剪路径还是全量路径。$\\rho$ 无法在请求开始前精确知道，只能在线估计：用 KWS 候选时长之和除以 utterance 时长得到每请求的 $\\rho$，再对滑动窗口取统计量。当估计值接近 1 或兜底触发率上升时，裁剪的净收益转负，应切回全量解码。</p>\n<p>切换的代价是状态机的复杂度：同一服务实例内两条路径共享前端缓存与 KV 管理，切换时缓存布局与批调度策略都要重配，切换瞬间的批内请求可能处于半裁剪状态，需要排空或标记。工程判断是：把切换做成批级而非请求级决策，避免同一批内混跑两种路径导致调度器无法对齐窗口。具体例子：早高峰命令词请求占多数，$\\rho$ 估计值低，走裁剪路径，吞吐按关键词时长占比下降而提升；午后自由听写流量上升，$\\rho$ 估计值逼近 1，调度器切回全量路径，此时若仍强行裁剪，调度与拼接开销使吞吐低于全量解码，召回也因窗口错位而下降。这一步落在具体机制上：路径选择由 $\\rho$ 的在线估计与兜底触发率共同驱动，二者构成裁剪方法能否启用的判据。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-13\">十三 · 边界条件：ρ、漏检率与窗口错位三者共同决定是否该启用</h3>\n<p>关键词聚焦 ASR 的收益不是无条件成立的，它被三个量同时约束：关键词时长占比 ρ、KWS 分支的漏检率、以及 KWS 时间戳与主 ASR 窗口的对齐误差。计算量近似为 <span class=\"formula\">$$\\mathrm{FLOPs}_{\\mathrm{focus}} \\approx \\rho\\cdot \\mathrm{FLOPs}_{\\mathrm{full}}$$</span>，但真实系统还要叠加 KWS 分支本身的开销与裁剪窗口的调度、拼接成本。当 ρ 接近 1（自由听写），裁剪后的窗口几乎覆盖整条 utterance，主 ASR 并未少算，反而多付了一次 KWS 前向与窗口重组的代价，吞吐会低于全量解码路径——这是必须按流量构成动态切换的场景，而不是靠调参能救回来的。工程判断的临界点在于：ρ 低于某个阈值时收益为正，而这个阈值由 KWS 的相对开销与窗口调度开销共同抬高，流量中命令词请求占比越高，越值得常驻 KWS 分支。</p>\n<p>失效条件里最危险的是漏检，它在噪声与口音下更易发生，且后果是静默的：关键词帧没有被送进主 ASR 的精细路径，输出直接缺失该词，下游 NLU 拿到的是残缺文本而非错误提示。因此部署配方必须带兜底策略——KWS 置信度低于门限或候选为空时回退全量解码，这条回退路径的触发频率本身就是监控指标。另一类失效是窗口错位：KWS 与主 ASR 若未共享同一份前端特征缓存，或时间戳存在偏移，裁剪窗口会把关键词截断在边界上，解码出半截音素。共享前端特征缓存不只是省一次特征提取的带宽，更是保证两条分支看到同一帧网格的前提。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>KWS 漏检</td><td>噪声、口音、低置信度候选</td><td>召回率下降，需回退全量解码，首包延迟抬升</td></tr><tr><td>ρ 接近 1</td><td>自由听写、长句连续语音</td><td>裁剪收益消失，调度与拼接开销使吞吐低于全量路径</td></tr><tr><td>窗口错位</td><td>特征缓存不一致、时间戳偏移</td><td>关键词被截断解码，需重解码，显存带宽二次消耗</td></tr></tbody></table>\n<p>从系统代价看，这条路径把压力从主 ASR 的算力与显存带宽转移到了调度器与前端缓存的带宽上：非关键词帧走低精度或低帧率路径仅保留上下文状态，省下的是主模型权重读取与激活带宽，但前端特征缓存要被两条分支同时读取，缓存容量与带宽成为新的瓶颈点。批处理侧，主 ASR 按裁剪窗口组 batch，可混合不同请求的窗口，但窗口长度方差大时 batch 利用率下降，调度开销随请求数增长。量化按分支分别配置——KWS 可用更激进精度，主 ASR 保留精细路径——是为了不让轻量分支的精度损失污染关键词定位。规模上限因此受 KWS 召回率与裁剪窗口调度开销双重约束，关键词密集场景应退回全量解码，否则召回与吞吐双输。</p>\n<h3 id=\"alg-asr-keyword-bifocal-sec-14\">十四 · 主公式的逐项拆解与 ρ 的物理含义</h3>\n<p>本方法的成本模型只有一条主公式，但每一项都对应一个可测量的系统量，值得逐项钉死：</p>\n<div class=\"formula\">$$\\text{FLOPs}_{\\text{bifocal}} \\approx \\text{FLOPs}_{\\text{KWS}} + \\rho \\cdot \\text{FLOPs}_{\\text{ASR}},\\quad \\rho = \\frac{T_{\\text{kw}}}{T_{\\text{utt}}} \\ll 1$$</div>\n<p>第一项 $\\text{FLOPs}_{\\text{KWS}}$ 是常驻流式前端的固定开销，它与 utterance 长度近似成正比但系数极小——KWS 分支的模型宽度、帧移、是否做帧级滑窗都决定这个系数。第二项才是被优化的对象：$\\text{FLOPs}_{\\text{ASR}}$ 是主模型对整段音频做精细编码加解码的原始成本，乘以 $\\rho$ 后被压缩。$\\rho$ 不是超参数，而是流量本身的统计量：$T_{\\text{kw}}$ 是 KWS 判定为关键词候选的帧总时长（含窗口外扩），$T_{\\text{utt}}$ 是整段 utterance 时长。命令词请求里 $T_{\\text{kw}}$ 通常是几百毫秒量级而 $T_{\\text{utt}}$ 可达数秒，$\\rho$ 落在很小的区间；自由听写时 $T_{\\text{kw}}$ 逼近 $T_{\\text{utt}}$，$\\rho \\to 1$，第二项退化回全量成本，此时第一项纯属额外支出。</p>\n<p>推导的关键一步在于：主 ASR 的成本对输入帧长并非严格线性。声学编码器在裁剪窗口上仍要做卷积感受野的边界填充、注意力层的序列长度虽缩短但 batch 内不同窗口长度需 padding 对齐，解码器自回归步数则与关键词 token 数挂钩而非帧数。因此更准确的写法应把主模型成本拆成编码项与解码项：</p>\n<div class=\"formula\">$$\\text{FLOPs}_{\\text{focus}} \\approx \\text{FLOPs}_{\\text{KWS}} + \\rho \\cdot C_{\\text{enc}} + \\sigma \\cdot C_{\\text{dec}}$$</div>\n<p>其中 $\\sigma$ 是关键词 token 数占全量转写 token 数的比例，$C_{\\text{enc}}$、$C_{\\text{dec}}$ 分别为全量编码与解码成本。工程上常出现 $\\sigma &lt; \\rho$ 的情形（关键词短、但窗口外扩大），此时解码侧节省比编码侧更彻底；反之若窗口外扩过宽，$\\rho$ 被 padding 放大，节省被吃掉。这就是为什么裁剪窗口的边界策略必须与 KWS 时间戳精度联合标定，而不是简单按固定毫秒外扩。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-15\">十五 · 窗口裁剪的几何推导与错位代价</h3>\n<p>设 KWS 输出的关键词候选区间为 $[t_s, t_e]$，调度器实际送入主 ASR 的窗口为 $[t_s - \\delta_l,\\ t_e + \\delta_r]$，则有效占比为：</p>\n<div class=\"formula\">$$\\rho_{\\text{eff}} = \\frac{(t_e - t_s) + \\delta_l + \\delta_r}{T_{\\text{utt}}}$$</div>\n<p>$\\delta_l$、$\\delta_r$ 不是拍脑袋的常数，它们由两个物理量夹逼：一是主 ASR 声学编码器的左感受野，窗口左边界若切在关键词首音素之前不足一个感受野，首音素的特征会被边界填充污染；二是解码器的语言模型上下文，关键词首 token 的预测依赖前文若干帧的隐状态。因此 $\\delta_l$ 的下界是感受野加最小上下文帧数，$\\delta_r$ 的下界是关键词尾音素的拖尾与解码器回看需求。上界则由 $\\rho_{\\text{eff}}$ 的吞吐预算反推：窗口每多一帧，batch 内所有请求的 padding 对齐成本都上升。</p>\n<p>错位的代价是双重的。若窗口右移不足，关键词尾音被截断，主 ASR 输出残缺 token，下游 NLU 拿到半截命令；若 KWS 时间戳本身有系统性偏移（前端特征缓存与 KWS 分支帧移不一致时常见），裁剪窗口整体错位，此时即使 $\\rho_{\\text{eff}}$ 很小，召回率也塌陷。这类失败不会表现为延迟或吞吐异常，只会表现为关键词识别率下降，因此监控必须把 KWS 时间戳与主 ASR 解码结果的边界一致性做成独立指标，而不是只看端到端 WER。共享前端特征缓存正是为了消除帧移不一致这一错位源：KWS 与主 ASR 从同一份帧特征取数，时间戳坐标系天然对齐，裁剪窗口无需再做帧率换算。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-16\">十六 · 伪代码：从帧流到拼接结果</h3>\n<p>下面给出可直接落地的调度骨架，重点在状态机与回退路径，而非模型内部：</p>\n<ul>\n<li>前端特征环缓冲：以固定帧移持续写入共享特征缓存，KWS 分支与主 ASR 分支各自持有读指针，读指针偏移量在初始化时对齐。</li>\n<li>KWS 滑窗推理：对每个新帧做轻量前向，输出候选关键词标签与起止帧号；候选进入待定队列，连续多帧一致才确认，抑制单帧误触发。</li>\n<li>窗口生成：以确认的起止帧号加 $\\delta_l$、$\\delta_r$ 生成裁剪区间，同时记录该区间的特征缓存版本号，防止环缓冲回绕导致取到旧帧。</li>\n<li>主 ASR 批调度：把多个请求的裁剪窗口按长度分桶，同桶内 padding 对齐后组 batch；窗口长度差异过大时宁可拆批，避免短窗口被长窗口拖慢。</li>\n<li>非关键词帧廉价路径：低帧率或低精度前向，只更新上下文隐状态，不产生 token；其输出仅用于维持解码器状态连续性。</li>\n<li>拼接与回退：关键词文本按时间戳插入转写骨架；若 KWS 置信度低于阈值或窗口内主 ASR 输出为空，触发全量解码兜底。</li>\n</ul>\n<p>伪代码层面的关键判断是回退触发条件必须廉价可算。把“窗口内主 ASR 输出 token 数为零”作为兜底信号是可行的，因为它不需要额外模型；但它在关键词确实为静音或噪声时会误触发全量解码，浪费算力。更稳的做法是联合 KWS 置信度与窗口内声学能量：置信度低且能量高于静音门限才回退。回退本身有代价——一次全量解码的延迟远高于裁剪路径，若回退率在噪声环境下升高，首包延迟的 SLO 会被尾部分布拉爆，因此回退率必须作为容量规划的一等指标。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-17\">十七 · 系统代价：带宽、显存与批内碎片</h3>\n<p>算力节省不等于系统吞吐等比提升。主 ASR 的权重在裁剪路径下仍需完整驻留显存，权重读取的带宽成本不随 $\\rho$ 缩小——每处理一个裁剪窗口，编码器与解码器的权重都要从 HBM 过一遍。当 $\\rho$ 很小时，单请求的有效计算被压得很低，权重带宽反而成为瓶颈：算术强度下降，GPU 从计算受限滑向带宽受限。这就是为什么本方法在 batch 混合上必须做文章——把多个请求的裁剪窗口拼进同一 batch，让一次权重读取服务多个窗口，把算术强度拉回来。批内碎片是这里的隐性成本：窗口长度分布偏斜时，padding 让短窗口的有效利用率下降，分桶策略不当会使实际吞吐低于理论 $\\rho$ 所预示的值。</p>\n<p>显存侧的压力主要来自 KV cache 与上下文状态。裁剪路径下主 ASR 只为关键词窗口建 KV，KV 占用随 $\\sigma$ 缩小，这对长 utterance 的命令词请求是实打实的显存节省；但非关键词帧的廉价路径仍需保留上下文隐状态，这部分状态若按全帧率缓存，显存节省就被抵消。工程取舍是把廉价路径的状态做降采样或量化压缩，只保留解码器恢复所需的最小上下文。功耗维度上，KWS 常驻意味着前端永远有活动负载，空闲期无法完全下电，这对始终在线的语音助手是常态代价，需在容量规划中按常驻功耗计入基线。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-18\">十八 · 一个具体例子：命令词请求的端到端账</h3>\n<p>取一个典型语音助手请求：用户说一句含唤醒后命令词的短句，整段 utterance 数秒，其中命令词本身只占其中一小段，其余为静音、呼吸、环境噪声与少量填充词。KWS 分支在流式前端逐帧滑窗，确认命令词起止帧后，调度器裁出含左右外扩的窗口送入主 ASR。主 ASR 只对该窗口做精细编码与自回归解码，得到命令词文本；窗口外的帧走低精度路径，仅维持上下文状态。最终拼接出的转写只含命令词，直接送 NLU 做意图解析。</p>\n<p>这笔账里，主 ASR 的编码与解码成本按 $\\rho$、$\\sigma$ 缩小，batch 内混入多个同类请求后权重带宽被摊薄，吞吐提升来自算力与带宽两侧；首包延迟由 KWS 确认延迟加主 ASR 窗口解码延迟构成，由于窗口短，解码步数少，首包通常快于全量路径。代价端：KWS 漏检在噪声与口音下更易发生，漏检即意味着该请求走廉价路径、关键词未被精细解码，召回率下降且下游 NLU 拿到空意图；此时兜底策略必须能识别“窗口内无有效输出”并回退全量，回退请求的延迟会显著高于裁剪路径，构成尾延迟。若同一时段自由听写流量占比上升，$\\rho$ 逼近 1，裁剪收益消失而调度与拼接开销仍在，吞吐反低于全量解码——这正是场景切换逻辑必须按流量构成动态启用的原因，而不是把本方法无条件设为默认路径。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-19\">十九 · 推导的边界：何时公式失效</h3>\n<p>主公式的线性假设在两种情形下失效。其一是窗口极短时，主 ASR 的固定开销（编码器边界处理、解码器首步、kernel 启动）不再可忽略，$\\rho \\cdot \\text{FLOPs}_{\\text{ASR}}$ 低估了实际成本，此时应把固定开销单列一项，否则容量规划会高估吞吐。其二是 batch 内窗口长度高度异质时，padding 使有效 $\\rho$ 高于名义 $\\rho$，公式需用批内平均有效占比替代单请求 $\\rho$。这两种失效都指向同一个工程判断：本方法的收益上界由 KWS 召回率与裁剪窗口调度开销共同夹逼，公式只描述理想算力账，真实吞吐必须用批内碎片与回退率修正后再做容量决策。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-20\">二十 · 裁剪窗口的收益边界与漏检代价</h3>\n<p>把 bifocal 公式拆开看，真正决定系统行为的是 ρ 的分布而非均值。$\\rho = T_{\\text{kw}}/T_{\\text{utt}}$ 在命令词请求上远小于 1，但同一流量里混入自由听写后，ρ 迅速逼近 1，此时 $\\text{FLOPs}_{\\text{bifocal}} \\approx \\text{FLOPs}_{\\text{KWS}} + \\rho\\cdot\\text{FLOPs}_{\\text{ASR}}$ 中的 KWS 项变成纯开销，裁剪调度与结果拼接还要额外占用 CPU 侧调度线程和一次窗口重组的显存拷贝。工程判断应落在按流量构成动态启用：以滑动窗口统计近端请求的 ρ 分位数，超过阈值即整体退回全量解码路径，而不是逐请求试探。</p>\n<p>失效条件集中在时间戳对齐上。KWS 输出的候选区间必须与主 ASR 的帧索引共享同一前端特征缓存；一旦两分支的帧移或缓存版本不一致，裁剪窗口就会偏移，关键词首尾被截断，解码出的文本残缺而调度器无从察觉。伪代码上应把窗口定义为 $[\\,t_s-\\delta,\\; t_e+\\delta\\,]$，δ 取覆盖 KWS 感受野的余量，并在拼接前校验窗口内声学编码的帧数与时间戳单调性，不满足即触发全量回退。</p>\n<p>漏检是另一条硬边界：噪声与口音下 KWS 召回下降，未被定位的关键词永远进不了精细路径，端到端召回率被 KWS 上限封死。兜底策略不能只做“低置信度回退”，而要对 KWS 打分低于阈值的整段 utterance 直接走全量解码，代价是这部分流量失去 ρ 收益。系统代价上，裁剪窗口批处理虽能混合不同请求的窗口以抬高主 ASR 的 batch 利用率，但窗口长度方差大时 padding 浪费显存带宽，首包延迟受 KWS 常驻分支的推理时延支配，主 ASR 的精细路径反而退居次位。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>ρ 量级</th><th>主 ASR 负载</th><th>主要风险</th></tr></thead><tbody><tr><td>命令词请求</td><td>远小于 1</td><td>仅窗口帧</td><td>KWS 漏检</td></tr><tr><td>混合流量</td><td>中等</td><td>窗口+回退</td><td>调度开销</td></tr><tr><td>自由听写</td><td>接近 1</td><td>全量帧</td><td>收益消失</td></tr></tbody></table>\n<h3 id=\"alg-asr-keyword-bifocal-sec-21\">二十一 · 请求形态决定 ρ 的分布，而不是平均值</h3>\n<p>关键词聚焦推理的负载配方，第一步不是问“平均 ρ 是多少”，而是问“ρ 的分布长什么样”。同一套 KWS+ASR 双分支栈，在语音助手的命令词流量里，单条 utterance 的 ρ 往往落在很低的区间——用户说“打开客厅灯”“下一首”“音量调高”，关键词只占整句的一小段，其余是唤醒词、语气词、停顿与背景。而在自由听写、会议转写、客服质检这类流量里，ρ 逼近 1，因为几乎每一帧都承载需要精细解码的语义内容。工程上真正要建模的是混合流量的 ρ 直方图：如果 80% 的请求 ρ<0.2，那么按窗口裁剪的批处理能把主 ASR 的有效帧数压到全量路径的一小部分；如果 ρ 呈双峰、长尾拖到 0.9，调度器就必须准备两条路径并按请求特征分流，而不是指望一个 batch 内所有窗口都短。</p>\n<p>这里的关键机制是“按窗口而非按请求”组批。传统连续批处理以请求为粒度拼 batch，序列长度差异造成 padding 浪费；关键词聚焦把主 ASR 的输入从整条 utterance 换成裁剪窗口，batch 内每个 slot 是一个窗口，窗口长度由 KWS 时间戳决定。于是批大小不再受最长 utterance 支配，而受最长窗口支配。代价转移到了调度侧：窗口长度方差大时，短窗口 slot 会提前空转，GPU 的 SM 占用率被最长窗口拉低。一个具体例子：一个 batch 里混入 8 个命令词窗口（每个几十帧）和 1 个误入的自由听写请求（上千帧），后者会把整个 batch 的完成时间拖到与前缀解码全量路径相当，ρ 收益被单条长尾请求吃掉。配方上要么给长窗口单独排队，要么对超阈值请求直接切全量路径。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-22\">二十二 · 长度分布与裁剪窗口的批内对齐</h3>\n<p>窗口长度分布直接决定 tcgen05 MMA 的利用率。Blackwell 的 2-SM MMA 与 TMEM 累加器对 tile 形状敏感：当窗口帧数落在 MMA tile 的整数倍附近时，矩阵乘的尾块浪费小；当窗口长度参差、大量落在 tile 边界之外时，每个 slot 都要付尾块代价。裁剪窗口的帧数由 KWS 时间戳的粒度决定——时间戳越粗，窗口越容易对齐到固定帧块，批内形状越整齐；时间戳越细，窗口越贴合真实关键词边界，ρ 更小但形状更碎。这是一个显式的工程折衷：粗粒度时间戳换批内规整与吞吐，细粒度时间戳换更低的 ρ 与更少的无效帧。</p>\n<div class=\"formula\">$$\\text{FLOPs}_{\\text{bifocal}} \\approx \\text{FLOPs}_{\\text{KWS}} + \\rho \\cdot \\text{FLOPs}_{\\text{ASR}},\\quad \\rho = \\frac{T_{\\text{kw}}}{T_{\\text{utt}}} \\ll 1$$</div>\n<p>把公式拆到批维度：一个 batch 的有效 ASR 计算是各 slot 窗口 FLOPs 之和，而硬件按最长窗口的 tile 形状分配时间片，所以实际吞吐取决于 ρ 的均值与窗口长度的方差两者。均值决定省多少，方差决定省下来的算力有多少被空转抵消。显存带宽侧的代价同样按窗口计：主 ASR 精细路径要读权重、读 KV、写激活，窗口越短，单位请求的权重读取次数越多，权重带宽占比上升，算术强度下降。命令词窗口短到一定程度后，主 ASR 变成带宽受限而非算力受限，此时继续缩小 ρ 对延迟帮助有限，反而增加每请求的固定开销（窗口建立、上下文状态拼接、结果合并）。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-23\">二十三 · 并发与批大小的配方边界</h3>\n<p>并发上升时，KWS 分支与主 ASR 分支的负载比例会漂移。KWS 常驻流式前端，按帧处理，其成本随总音频时长线性增长，与 ρ 无关；主 ASR 成本随 Σρ 增长。因此高并发下 KWS 分支从“轻量常驻”变成不可忽略的固定税：当 ρ 很低、主 ASR 被压得很扁时，KWS 的 FLOPs 在总 FLOPs 中的占比上升，公式里的第一项不再可略。配方判断是：并发越高、ρ 越低，越要把 KWS 做成真正的窄模型并共享前端特征缓存，避免重复提特征；否则省下来的主 ASR 算力被前端重复计算吃掉。</p>\n<p>批大小还有一条硬边界来自裁剪窗口的调度开销。每个请求都要经历“KWS 输出时间戳→调度器裁剪→主 ASR 建窗口→结果拼接”这条链，链上每一步都有 CPU 侧与 GPU 侧的同步点。批越大，单批内窗口数越多，调度器排序与拼接的 CPU 时间越可观；批越小，GPU 占用率越难维持。存在一个使吞吐最大的批大小区间，它由窗口长度方差和调度链延迟共同决定，而不是单调地“越大越好”。首包延迟为主的 SLO 会把批大小压向小值：命令词请求的用户期待是说完即响应，攒大批会直接违反首包预算。于是配方常见形态是“小批、高频、窗口短”，用流水线掩盖调度开销，而不是靠大批摊薄。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-24\">二十四 · 负载不对时的三种塌陷</h3>\n<p>第一种塌陷是 ρ 漂移。流量构成从命令词转向自由听写时，ρ 从远小于 1 升到接近 1，公式第二项的节省消失，但裁剪调度、窗口拼接、双分支同步的固定开销仍在，总吞吐低于直接全量解码。这不是渐进退化，而是收益符号反转：原本省下的算力被调度开销抵消后变成净损失。工程上必须按流量构成动态启用，用 ρ 的在线估计（例如滑动窗口内 KWS 命中时长占比）触发路径切换，而不是静态配置。</p>\n<p>第二种塌陷是漏检放大。KWS 在噪声、口音、远场条件下召回率下降，漏掉的关键词不会被送入精细解码，直接表现为识别召回下降。更隐蔽的是时间戳偏移：KWS 与主 ASR 共享前端特征缓存时，若两分支的帧对齐或缓存版本不一致，裁剪窗口会错位，关键词被截断在窗口边界外，解码出半截文本。这类错误不报错、不降级，只是静默地少识别，监控上表现为关键词命中率下滑而延迟指标正常。兜底策略是漏检回退全量解码，但回退本身有代价：回退请求走全量路径，等于在混合流量里插入长尾，批内对齐被破坏。</p>\n<p>第三种塌陷是批内污染。一个 batch 混入少量长窗口请求，会把整批的完成时间拉长，短窗口 slot 空转，GPU 利用率与尾延迟同时恶化。配方上要么按窗口长度分桶排队，要么设窗口长度上限、超限请求走独立路径。这三种塌陷的共同点是：它们都由负载配方与流量构成的不匹配触发，而不是模型或算子本身的问题；调优 kernel 无法修复配方错配。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-25\">二十五 · 配方与部署形态的耦合</h3>\n<p>负载配方还决定部署形态。命令词为主的流量适合单机推理栈：KWS 常驻前端、主 ASR 按窗口调度、共享特征缓存放在同一节点内，避免跨节点传特征带来的带宽与延迟。此时 NVLink 5 的域内带宽用于窗口批的激活与 KV 传输，而不是跨节点。自由听写为主的流量则倾向分离式预填/解码，预填吃长序列算力、解码吃带宽，与关键词聚焦的短窗口批形态不同。把关键词聚焦栈硬套到自由听写流量上，等于用为短窗口设计的调度器去跑长序列，批内对齐与窗口裁剪都失效。</p>\n<p>量化配置也随配方分叉：KWS 分支可用更激进的低比特精度，因为它只做定位、输出时间戳，数值误差对最终文本影响有限；主 ASR 精细路径保留较高精度，因为窗口内的声学细节直接决定关键词文本正确性。若两分支共用一套量化策略，要么 KWS 过度精确浪费带宽，要么主 ASR 精度不足导致关键词错识。功耗侧同理：KWS 常驻意味着前端始终有活动功耗，命令词流量下这部分功耗摊到极短的 ASR 窗口上，单位请求的能效比取决于 KWS 能否在无语音时真正休眠，而不是空转等帧。</p>\n<p>最终落到一条工程判断：关键词聚焦 ASR 的负载配方是一个以 ρ 分布为自变量、以窗口长度方差为约束、以首包延迟为目标的联合配置问题。ρ 低且方差小，裁剪批处理是净收益；ρ 高或方差大，调度开销与批内污染会把收益吃掉，此时退回全量解码不是保守，而是正确。配方切换的触发条件应当写进调度器，用在线 ρ 估计与窗口长度上限两个信号共同决定，而不是靠离线流量画像一次性设定。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-26\">二十六 · 关键词聚焦 ASR 的负载配方与失效边界</h3>\n<p>这套方案只对一种流量形态成立：<strong>关键词/命令词请求为主、utterance 内关键词稀疏</strong>的语音助手流量。此时 KWS 分支常驻流式前端，主 ASR 按裁剪窗口批处理，SLO 以首包延迟为主，batch 内可混合来自不同请求的裁剪窗口——因为每个窗口都很短，拼批不会显著拉长单请求的尾延迟。计算量节省可近似写成 <span class=\"formula\">$$\\mathrm{FLOPs}_{\\mathrm{focus}} \\approx \\rho\\cdot \\mathrm{FLOPs}_{\\mathrm{full}}$$</span>，其中 $\\rho$ 是关键词时长占 utterance 的比例。$\\rho$ 越小，主 ASR 精细解码的帧数越少，节省越多；反之，自由听写时 $\\rho$ 接近 1，裁剪收益消失。工程上判断是否启用，先看流量构成：若关键词请求占比高、且 utterance 内关键词稀疏，裁剪窗口调度才划算。</p>\n<p>负载不对时，代价会以两种方式出现。第一种是<strong>召回率下降</strong>：KWS 漏检使关键词未被精细解码，而漏检在噪声与口音下更易发生；漏检一旦发生，下游 NLU 拿到的就是拼接后的残缺文本，用户感知为“没听懂”。第二种是<strong>吞吐反降</strong>：自由听写场景关键词占比接近全部帧，裁剪收益消失，调度与拼接开销反使吞吐低于全量解码。更隐蔽的失败是 KWS 与主 ASR 前端特征缓存不一致或时间戳偏移，导致裁剪窗口错位，关键词被截断解码——这类错误不会报错，只会让识别结果变差。因此必须设置漏检回退到全量解码的兜底策略，并让 KWS 与 ASR 共享前端特征缓存，避免重复提取与时间戳漂移。</p>\n<p>系统代价要按分支分别核算。KWS 分支轻量、可常驻流式前端，首包延迟低，量化可用更激进的精度；主 ASR 保留精细路径，非关键词帧走低精度或低帧率路径仅保留上下文状态，以省显存带宽。裁剪窗口调度本身有开销：窗口越短、请求越碎，调度器与拼接逻辑占用的 CPU/GPU 时间越不可忽略，batch 混合不同请求的裁剪窗口时还要处理窗口长度不齐带来的填充浪费。规模上限受 KWS 召回率与裁剪窗口调度开销约束，不是受主 ASR 算力约束——这意味着扩容时先看 KWS 的召回曲线与调度器的批处理效率，而不是先加 GPU。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>$\\rho$ 量级</th><th>主 ASR 精细帧</th><th>主要风险</th></tr></thead><tbody><tr><td>命令词/唤醒词</td><td>很小</td><td>仅关键词窗口</td><td>KWS 漏检、时间戳偏移</td></tr><tr><td>短问答</td><td>中等</td><td>关键词附近窗口</td><td>窗口错位截断</td></tr><tr><td>自由听写</td><td>接近 1</td><td>几乎全部帧</td><td>收益消失、吞吐反降</td></tr></tbody></table>\n<p>工程判断落在<strong>按流量构成动态启用</strong>：以关键词请求为主的时段走裁剪路径，检测到自由听写占比上升或 KWS 召回率下滑时切回全量解码。切换逻辑本身要计入 SLO——切换瞬间在途请求的窗口已按旧路径裁剪，必须允许其完成或重放，否则会出现一批被截断的识别结果。这套方案与全量 ASR 的差别不在模型，而在计算分配：全量解码对所有帧一视同仁，本方法把主模型算力集中到关键词窗口；代价是引入漏检风险与场景切换逻辑，适用边界由 KWS 召回率与裁剪调度开销共同划定，越界即召回与吞吐双输。</p>\n<h3 id=\"alg-asr-keyword-bifocal-sec-27\">二十七 · 硬件档位与分支放置</h3>\n<p>关键词聚焦 ASR 的部署配方首先要回答一个问题：KWS 分支和主 ASR 分支各自放在哪一级硬件上。这不是简单的“都塞进 GPU”就能了事，因为两条分支的负载形态完全不同——KWS 是常驻、逐帧、极低算力的流式前端，主 ASR 是突发、按窗口、高算力的精细解码器。把两者放在同一 SM 上会让 KWS 的逐帧唤醒打断主 ASR 的大块 MMA 流水；放在同一张卡的不同 SM 上则要处理前端特征缓存的共享一致性。工程上可复现的做法是：KWS 常驻于靠近音频入口的那一级（单卡内的少量 SM，或 GB200 NVL72 中承担前端接入的节点），主 ASR 放在算力档位更高的 GPU 上，两者通过共享的前端特征缓存衔接，而不是各自重跑一遍前端。</p>\n<p>档位选择的判据是 ρ 的分布而非平均值。若流量以命令词为主、ρ 集中在很小的区间，主 ASR 的实际占用时间短，硬件档位可以按“峰值窗口并发”而非“全量帧吞吐”来配；若流量中混有相当比例的自由听写，ρ 接近 1，主 ASR 退回全量路径，此时档位必须按全量解码的算力上限配，否则切换瞬间就会出现排队。B200/B300 这一档的意义不在于跑 KWS，而在于承载裁剪窗口的批处理与 tcgen05 路径上的精细声学编码；把 KWS 也压到这一档上只会浪费 TMEM 与 2-SM MMA 的调度粒度。</p>\n<p>代价体现在两个方向：KWS 分支若放在过低的档位（例如纯 CPU 或低端边缘芯片），逐帧延迟会拉高首包时间；若放在过高档位，则常驻占用挤占主 ASR 的显存与带宽。可复现的配置思路是给 KWS 划出固定的小额 SM 配额与独立的特征缓存区，主 ASR 使用剩余算力，两者不共享 MMA 流水，只共享缓存。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-28\">二十八 · 并行拓扑：窗口批而非帧批</h3>\n<p>主 ASR 的并行拓扑要围绕“裁剪窗口”这一调度单位来设计，而不是围绕原始帧。全量解码时，批内各请求的帧长接近，容易做定长 padding 与连续批处理；关键词聚焦后，每个请求的裁剪窗口长度由 KWS 输出的时间戳决定，窗口长短不一，且窗口在时间轴上的位置各异。若仍按帧维做张量并行切分，切分点会落在不同请求的不同时间位置上，通信与掩码都变得零碎。</p>\n<p>更稳的拓扑是按窗口做批：调度器把若干请求的裁剪窗口聚成一个批，窗口内的帧做定长对齐（不足补上下文状态帧），张量并行只沿模型层维切分，不沿时间维切分。这样 2-SM MMA 的配对与 TMEM 的分配都落在稳定的层维上，窗口长度差异只影响批内 padding 比例，不影响集合通信的形态。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{batch} = \\{\\text{window}_i\\}_{i=1}^{B},\\quad \\text{pad}(\\text{window}_i) \\to L_{\\max},\\quad \\text{TP split along layer dim only}$$</div>\n<p>代价是 padding 浪费：当批内窗口长度方差大时，短窗口被拉到最长窗口的长度，有效算力利用率下降。缓解手段是按窗口长度分桶，桶内再做连续批处理，桶间不混批。这与全量解码的连续批处理不同——后者的批是随时间滑动的，前者的批是随窗口到达而聚合的，调度参数（最大批大小、桶边界、等待超时）需要单独整定。</p>\n<p>另一个拓扑问题是 KWS 与主 ASR 的流水衔接。KWS 逐帧输出候选与时间戳，主 ASR 的窗口要等 KWS 判定完成才能裁剪，因此两者之间存在一个判定延迟。若把 KWS 与主 ASR 放在同一流水线上串行，首包延迟等于判定延迟加窗口解码延迟；若让 KWS 略微超前于主 ASR（提前若干帧给出候选），则窗口可以在候选确认前预取特征，缩短首包。这个超前量是调度参数，需要按 KWS 的判定稳定性整定，超前过多会引入误裁剪。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-29\">二十九 · 量化方案：按分支分治</h3>\n<p>量化不能对两条分支用同一套方案。KWS 分支是轻量卷积或小 Transformer，对数值误差的容忍度高，可以用更激进的低比特格式换取常驻占用的下降与逐帧带宽的节省；主 ASR 的精细声学编码与解码对数值敏感，尤其在关键词边界帧上，过度量化会让音素判别退化，直接反映为关键词识别错误。因此配方是：KWS 走激进低比特，主 ASR 保留精细路径（FP8 或 NVFP4 中较保守的档位），非关键词帧的低精度/低帧率路径则可以用更低的精度，因为它只保留上下文状态、不产出文本。</p>\n<p>这里的关键机制是分支间的精度隔离：KWS 的量化误差不会传播到主 ASR 的输入，因为两者共享的是前端特征缓存而非 KWS 的中间表示。若共享的是 KWS 的量化后特征，误差会叠加到主 ASR 的窗口解码上，关键词边界帧的声学细节被抹平。可复现的做法是缓存前端提取的浮点或高精度特征，KWS 与主 ASR 各自从缓存读取并按自己的精度路径处理，缓存本身不做激进量化。</p>\n<p>代价是显存与带宽的分裂管理：KWS 的低比特权重常驻占用小，但主 ASR 的精细路径权重占用大，且窗口批的激活值随批大小波动。非关键词帧走低精度路径时，上下文状态的保真度下降，长 utterance 中远离关键词的上下文可能失真，影响关键词边界的判定。量化方案因此要与 ρ 联动：ρ 小的场景下非关键词帧占比高，低精度路径的误差累积更明显，需要定期用高精度帧刷新上下文状态。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-30\">三十 · KV 策略：窗口局部缓存与上下文状态分离</h3>\n<p>关键词聚焦 ASR 的 KV 策略与全量解码有本质区别：主 ASR 只对裁剪窗口做精细解码，KV cache 的主体应围绕窗口局部建立，而非围绕整条 utterance 线性增长。窗口内的 KV 按窗口长度分配，窗口外的历史只保留压缩后的上下文状态（低精度或低帧率的摘要表示），不保留逐帧 KV。这样显存占用由窗口长度与批内窗口数决定，而不是由 utterance 总长决定。</p>\n<p>机制上，调度器在裁剪窗口时同时决定 KV 的分配：窗口起点之前的帧只贡献上下文状态向量，窗口内的帧建立完整 KV，窗口终点之后的帧在解码完成后释放。伪代码思路是：</p>\n<div class=\"formula\">$$\\text{KV}_{\\text{window}} = \\text{alloc}(L_{\\text{kw}}),\\quad \\text{ctx} = \\text{compress}(\\text{frames}_{&lt;t_{\\text{start}}}),\\quad \\text{free}(\\text{KV}_{\\text{window}}) \\text{ after decode}$$</div>\n<p>代价是上下文状态的压缩损失：远离关键词的语音内容被压成摘要后，若关键词判定依赖远距离语义（例如命令词前的称呼或否定词），摘要可能丢失关键信息，导致关键词文本拼接错误。缓解手段是在窗口两侧保留少量高精度邻接帧作为边界缓冲，缓冲长度是调度参数。</p>\n<p>另一个代价是 KV 的碎片化：窗口批内各请求的窗口长度不一，KV 分配呈碎片状，显存池的利用率下降。按窗口长度分桶同样适用于 KV 分配，桶内 KV 块大小一致，桶间独立回收。这与全量解码的 PagedAttention 式块管理不同——后者的块随序列增长而追加，前者的块在窗口确定时就固定，回收时机也更早。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-31\">三十一 · 调度参数与漏检兜底</h3>\n<p>调度参数的核心是一组联动量：KWS 判定阈值、窗口裁剪的边界缓冲长度、窗口批的最大批大小与桶边界、漏检回退的触发条件。这些参数不能各自独立整定，因为漏检率与裁剪开销是一对矛盾——阈值放低会提高召回但增加误裁剪（把非关键词帧拉进精细解码），阈值放高会减少裁剪开销但漏检上升，漏检的关键词不会被精细解码，直接表现为召回率下降。</p>\n<p>兜底策略是配方中不可省略的一环：当 KWS 的候选置信度落在灰区，或窗口解码结果与 KWS 候选不一致时，回退到全量解码路径重跑该 utterance。回退的代价是全量解码的算力与延迟，因此回退率必须作为容量规划的输入量——回退率乘以全量解码成本，叠加到关键词路径的成本上，才是真实的算力需求。若回退率随噪声与口音上升，容量规划要按最差流量段配，而不是按平均。</p>\n<p>失败模式还包括缓存不一致与时间戳偏移：KWS 与主 ASR 若各自重跑前端，特征缓存不一致会让裁剪窗口错位，关键词被截断解码；时间戳偏移同理。可复现的配置要求前端只提取一次、两条分支读同一份缓存、时间戳以同一时钟基准对齐。调度参数中的窗口起点要留出对齐余量，余量大小按前端帧移与 KWS 判定延迟整定。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-32\">三十二 · 可复现配置思路与场景切换</h3>\n<p>把上述选择落成一个可复现的配置，顺序是：先按流量构成定 ρ 的分布与回退率，据此定主 ASR 的硬件档位与并行拓扑（窗口批、层维切分、按窗口长度分桶）；再定量化分治（KWS 激进低比特、主 ASR 精细、非关键词帧低精度、缓存不做激进量化）；再定 KV 策略（窗口局部 KV、上下文状态压缩、边界缓冲、分桶分配）；最后整定调度参数（判定阈值、边界缓冲、批大小与桶边界、回退触发）。每一步的代价都要回到容量规划：窗口批的 padding 浪费、KV 碎片、回退率乘全量成本，三者叠加才是真实占用。</p>\n<p>场景切换逻辑是配方的最后一块：当流量中自由听写占比上升、ρ 接近 1 时，裁剪收益消失，调度与拼接开销反使吞吐低于全量解码，此时应关闭关键词聚焦路径、整体退回全量解码。切换判据不能只看单条请求的 ρ，要看滑动窗口内的流量构成，避免在混合流量下频繁抖动。切换本身有状态迁移成本——KV 策略从窗口局部切到线性增长、批形态从窗口批切到帧批——因此切换要有滞回区间，滞回宽度按切换成本与抖动频率整定。</p>\n<p>这套配置的可复现性依赖于把每个参数与其代价显式绑定：KWS 的 SM 配额绑定首包延迟，窗口桶边界绑定 padding 浪费，回退率绑定容量上限，缓存一致性绑定召回率。工程判断落在一点上——关键词聚焦 ASR 的部署不是把两条分支拼起来，而是让调度器同时持有 ρ 的分布、回退率与窗口批的碎片状态，在收益消失前主动退回全量路径，而不是等吞吐掉下去再补救。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-33\">三十三 · 关键词聚焦 ASR 的部署边界：配方在什么条件下失效</h3>\n<p>这套配方成立的前提是流量构成与声学条件同时达标。硬件档位上，KWS 分支常驻流式前端，占用的是首包延迟路径上的常驻算力，因此它必须足够轻——轻到能与前端特征提取共享同一个 SM 波次而不引入额外排队；主 ASR 则按裁剪窗口批处理，batch 内混合来自不同请求的窗口，窗口长度不等会造成批内 padding 与变长调度开销。量化按分支分别配置：KWS 可用更激进的精度档位以换取常驻开销，主 ASR 的精细路径保留高精度，因为关键词窗口短、绝对算力小，牺牲精度换吞吐不划算。KV 策略上，非关键词帧走低精度或低帧率路径，只保留上下文状态而不保留完整 KV，这直接决定了显存带宽的节省幅度——但一旦回退到全量解码，被压缩的上下文无法无损还原，回退请求必须重跑前端。</p>\n<p>失效条件有三类，且互相耦合。第一是漏检：KWS 在噪声与口音下召回率下降，关键词未被精细解码，下游 NLU 直接拿到残缺文本；兜底策略是设置漏检回退到全量解码，但回退判据本身要消耗一次置信度评估，且回退请求会打乱批内窗口的同质性，把变长批退化成短批加长批的混合，吞吐反而劣化。第二是场景漂移：自由听写时关键词时长占比接近 1，裁剪收益消失，而裁剪调度与结果拼接的固定开销仍在，此时吞吐低于全量解码。第三是时间戳错位：KWS 与主 ASR 若前端特征缓存不一致或时间戳偏移，裁剪窗口会错位，关键词被截断解码，这类失败不表现为漏检而是表现为错字，更难在监控上捕获。</p>\n<div class=\"formula\">$$\\text{FLOPs}_{\\text{focus}} \\approx \\rho \\cdot \\text{FLOPs}_{\\text{full}},\\quad \\rho = \\frac{T_{\\text{kw}}}{T_{\\text{utt}}}$$</div>\n<p>工程判断落在 ρ 的动态估计上：调度器需按流量构成在线估计 ρ，低于阈值才启用裁剪路径，高于阈值切回全量解码，切换逻辑本身要有滞回以避免抖动。系统代价的账要算清——节省的是主 ASR 的算力与显存带宽，付出的是 KWS 常驻算力、窗口调度的变长批开销、以及回退路径的重复前端提取。规模上限因此不由主模型决定，而由 KWS 召回率与裁剪窗口调度开销共同约束；把 KWS 做得更准会推高其常驻成本，把窗口切得更细会推高调度开销，两者之间存在一个由流量 ρ 分布决定的最优点，配方必须围绕这个点配置而非固定一套参数。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>配方动作</th><th>主要代价</th></tr></thead><tbody><tr><td>ρ 低、噪声可控</td><td>裁剪路径 + 混合窗口批</td><td>KWS 常驻算力、变长批 padding</td></tr><tr><td>漏检率升高</td><td>回退全量解码</td><td>重复前端提取、批同质性破坏</td></tr><tr><td>ρ 接近 1</td><td>切回全量解码</td><td>切换滞回逻辑、拼接开销残留</td></tr></tbody></table>\n<h3 id=\"alg-asr-keyword-bifocal-sec-34\">三十四 · 裁剪窗口把算力账单改写成带宽账单</h3>\n<p>关键词聚焦推理的 FLOPs 账看起来极其漂亮：<span class=\"formula\">$$\\text{FLOPs}_{\\text{bifocal}} \\approx \\text{FLOPs}_{\\text{KWS}} + \\rho \\cdot \\text{FLOPs}_{\\text{ASR}},\\quad \\rho = \\frac{T_{\\text{kw}}}{T_{\\text{utt}}} \\ll 1$$</span> 当 $\\rho$ 落在 0.1 量级时，主 ASR 的矩阵乘工作量几乎被砍掉九成。但工程上真正先松动的往往不是算力，而是显存带宽与 KV cache 的驻留形态。全量解码时，主 ASR 的编码器对整段 utterance 一次性推进，激活张量形状规整、批内各请求长度接近，GEMM 的 M/N/K 三维都能填满；裁剪之后，每个请求的主 ASR 输入变成一段长度由 KWS 时间戳决定的短窗口，窗口长度在批内高度离散——有的请求关键词只有几百毫秒，有的因为连读或拖音拉到两秒。批处理时这些窗口必须 pad 到批内最长，pad 出来的帧不做有效计算却照样占显存、照样被搬进搬出。于是出现一个反直觉的拐点：$\\rho$ 越小，单请求算力越省，但批内窗口长度的方差越大，pad 浪费与调度碎片越严重，单位 token 的有效算力占比反而下降。</p>\n<p>具体机制上，调度器拿到的不是一条连续张量，而是一组 (request_id, start_frame, end_frame) 三元组。若沿用固定 shape 的静态批，就必须按批内最大窗口开 buffer，显存占用按 max 而非 mean 计；若改用连续批处理式的变长打包，则要在前端特征缓存里做非连续 gather，把分散的帧窗口拼进一块连续 staging buffer。后者省显存但引入一次额外的 HBM 读写：gather 的读带宽代价约等于窗口字节数乘以一个大于 1 的放大系数（非对齐访问、bank 冲突），在 HBM 已经接近饱和的 decode 阶段，这笔开销会直接吃掉裁剪带来的收益。工程判断是：当批内窗口长度标准差超过均值的一半时，静态批的 pad 浪费已经抵消 $\\rho$ 的节省，此时应改为按窗口长度分桶的变长批，或者干脆把短窗口请求聚成高并发小批、把长窗口请求单独走全量路径。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-35\">三十五 · 共享前端缓存决定了通信与重复计算的边界</h3>\n<p>KWS 与主 ASR 共享前端特征缓存，是本方法在系统层面唯一能站住的复用点。若两者各自做一遍 fbank/卷积前端，则前端 FLOPs 翻倍，且两份特征在 HBM 里各占一份，显存带宽开销按两倍计——在关键词稀疏的场景里，前端开销甚至可能超过被裁掉的主 ASR 计算，收益直接归零。共享缓存的实现形态决定了下游代价：把前端输出写进一块按帧索引的环形 buffer，KWS 分支顺序消费、主 ASR 按窗口随机回读，回读的地址跨度由时间戳决定。跨度过大时，L2 命中率下降，回读退化为纯 HBM 流式读，带宽代价按窗口字节数线性增长。</p>\n<p>更隐蔽的是时间戳对齐。KWS 输出的关键词起止帧若与前端缓存的帧索引存在偏移（下采样比、帧移、lookahead 填充不一致），裁剪窗口就会系统性错位，把关键词首音或尾音截掉。这类错误在离线评测里表现为召回率小幅下降，在线上则表现为“说了但没识别全”的零星投诉，极难定位。稳定性技巧是在缓存层维护一份帧号到绝对时间的映射，KWS 时间戳统一换算到该坐标系后再裁剪，并在窗口两端各留若干帧的 guard band——guard band 的代价是 $\\rho$ 略微上升，但它把错位风险从“截断”降为“多算几帧”，是划算的交换。</p>\n<p>通信维度上，单机栈内 KWS 与主 ASR 同卡或同节点，共享缓存走 HBM/L2 即可，没有集合通信；但一旦主 ASR 被拆到多卡张量并行（大模型主 ASR 在 NVL72 机柜内做 TP 或 EP），裁剪窗口的变长形状会让每卡的 all-reduce 负载不均，通信量按最大分片对齐，短窗口请求的通信效率显著低于全量批。此时把 KWS 与窗口裁剪调度放在前端节点、主 ASR 放在后端池，用请求级路由而非帧级路由，反而比帧级细粒度拆分更稳。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-36\">三十六 · 尾延迟：漏检回退是唯一的硬尾巴</h3>\n<p>关键词聚焦路径的稳态延迟由 KWS 常驻分支的首包时间加主 ASR 窗口解码时间构成，两者都短，P50 很好看。真正决定 SLO 的是回退路径：KWS 漏检或置信度低于阈值时，调度器必须把该请求切回全量解码，此时主 ASR 要对整段 utterance 重新编码解码，延迟从“窗口级”跳回“全量级”，量级差异足以击穿首包 SLO。漏检在噪声、口音、远场条件下更易发生，而语音助手的真实流量恰恰以这些条件为主，所以回退率不是长尾小数，而是稳定存在的一撮。</p>\n<p>系统代价的分配因此变得关键：回退请求不能与正常窗口请求混在同一批里，否则变长批被一条全量请求拉长，整批的 pad 与调度开销按最长者计，正常请求被无辜拖慢。可行做法是把回退请求路由到独立的全量解码队列，用单独的批处理配置与 SLO 预算，并在容量规划时按回退率预留一份全量解码的算力与显存——这份预留不能按均值算，要按回退请求的并发峰值算，因为回退往往在噪声事件（人群、车载、风噪）下成簇出现，呈现突发性而非泊松性。尾延迟的另一个来源是拼接：KWS 文本与主 ASR 窗口文本在结果层拼接后送 NLU，若两者来自不同批、不同步完成，拼接点就是一个同步屏障，慢的那一路决定整体完成时间。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-37\">三十七 · 功耗与规模：先崩的是调度器而不是张量核</h3>\n<p>规模上去以后，最先崩的通常不是 GPU 的算力或功耗墙，而是裁剪调度的元数据通路。每个流式请求每秒产生数十到上百个帧，每帧都要过 KWS 打分、候选聚合、时间戳输出，再驱动一次窗口裁剪决策；请求数从单机几百并发涨到机柜级数千并发时，这条 CPU 侧的轻量逻辑从“可忽略”变成瓶颈：调度队列的入队出队、窗口三元组的排序与分桶、特征缓存的索引维护，都是串行或低并行的操作，且与 GPU 上的解码不同步。表现为 GPU 利用率不高但吞吐上不去，尾延迟随并发上升而恶化——典型的调度器饱和而非计算饱和。</p>\n<p>功耗维度上，KWS 常驻分支的代价是“永远在线”：即使没有关键词请求，前端特征提取与 KWS 前向也在持续跑，这部分基础功耗不随流量下降而消失。在关键词稀疏、请求稀疏的夜间时段，常驻分支的功耗占比反而上升，能效比恶化。工程上可做的是按流量密度动态调整 KWS 的帧率与批大小，低峰期降帧率、拉大批间隔，用延迟换功耗；但降帧率会恶化时间戳精度，进而放大窗口错位风险，需与 guard band 宽度联动调整。</p>\n<p>显存侧的规模上限来自特征缓存与 KV cache 的双重驻留：主 ASR 的窗口解码虽短，但每个活跃请求仍要保留上下文状态（非关键词帧走低精度/低帧率路径所保留的那份状态），这份状态按请求数线性增长，与窗口长度无关。并发翻倍时，这份“上下文税”先于窗口激活撑爆显存，成为比 $\\rho$ 更硬的约束。容量规划应按活跃请求数乘以单请求上下文状态字节数来定上限，而不是按平均窗口长度估算。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-38\">三十八 · 场景切换逻辑本身就是一笔吞吐税</h3>\n<p>自由听写场景 $\\rho$ 接近 1，裁剪收益消失，必须退回全量解码。切换判据若只看单请求的 KWS 候选密度，会陷入抖动：一段话里关键词忽密忽疏，请求在两条路径间反复横跳，每次切换都要重建批、重排窗口、丢弃已积累的窗口状态，切换开销按次数计而非按帧计。稳定的做法是在会话级而非帧级做判据，用滑动窗口统计的 $\\rho$ 估计值加迟滞阈值，一旦判定为听写模式就在整个会话内锁定全量路径，避免逐帧决策。</p>\n<p>这笔切换税在混合流量下最贵：同一批里既有命令词请求又有听写请求时，两条路径的批处理配置、量化精度配置、SLO 预算都不同，混批会让任一条路径的效率都下降。可行的工程判断是按流量构成做物理隔离——命令词请求走裁剪池，听写请求走全量池，两池共享前端缓存但各自独立批调度；隔离的代价是资源利用率在单池低峰时下降，收益是两条路径的尾延迟互不污染。当听写流量占比上升到某个水平，裁剪池的边际收益被隔离带来的闲置抵消，此时应整体退回全量解码的单池形态，而不是硬撑双池。</p>\n<p>最终落在具体机制上：这套方法的规模上限由三个量共同决定——KWS 召回率决定回退率与尾延迟突发度，批内窗口长度方差决定 pad 浪费与变长打包的 gather 带宽代价，活跃请求数决定上下文状态的显存税。三者中任何一个先触顶，吞吐曲线就从线性转为平台，而此时 GPU 的张量核往往还有余量。调优的顺序应是先压窗口方差（分桶、guard band 联动）、再控回退簇（独立队列与预留）、最后才动并发上限，因为前两者是乘性因子，后者只是线性缩放。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-39\">三十九 · 裁剪窗口调度先撞上的不是算力，是带宽与尾延迟</h3>\n<p>关键词聚焦把主 ASR 的算力压到 ρ 倍，但显存带宽并不会同比例下降：共享前端特征缓存、KWS 分支常驻、主 ASR 权重与 KV 状态仍需常驻，非关键词帧的低精度/低帧率路径还要持续写入上下文状态。真正先崩的往往是批调度器——每个请求的裁剪窗口长度不同，混合批里最长窗口决定一次迭代的时长，短窗口请求被迫陪跑。设批内窗口长度为 \\(L_i\\)，单次迭代时延近似 \\(\\max_i L_i\\) 而非 \\(\\sum_i L_i\\)，于是尾延迟由少数长关键词请求支配；当流量中关键词密集请求比例上升，批内窗口方差变大，GPU 利用率被拖低，吞吐反而不如等长的全量解码批。这就是“规模上去以后哪里先崩”的第一处：不是 FLOPs，而是窗口长度方差带来的批效率塌陷。</p>\n<p>第二处是通信与状态同步。分离式预填/解码部署下，KWS 分支通常留在流式前端节点，主 ASR 在远端 GPU 池按窗口调度，裁剪窗口的时间戳与特征缓存必须跨节点对齐；时间戳偏移或缓存版本不一致会让窗口错位、关键词被截断解码，这类错误不报错、只表现为召回率静默下降。跨节点传输的窗口特征量虽小于全量帧，但请求数不变，NVLink/NIXL 上的小消息开销与首包延迟的 SLO 直接冲突：首包延迟要求 KWS 判定与窗口下发在一个 RTT 内完成，规模扩大后前端节点与解码池的排队时延成为主导项。功耗侧同样不对称——KWS 常驻使前端 GPU 无法深度降频，主 ASR 池则因批内窗口长短不一出现空转，整机功耗下降幅度小于算力节省幅度。</p>\n<p>失效条件可以写成一张判据表：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>系统表现</th><th>工程动作</th></tr></thead><tbody><tr><td>ρ 接近 1（自由听写）</td><td>裁剪收益消失，调度与拼接开销反超</td><td>按流量构成切回全量解码路径</td></tr><tr><td>KWS 召回率下降（噪声、口音）</td><td>关键词未被精细解码，召回静默损失</td><td>漏检回退全量解码兜底，监控回退率</td></tr><tr><td>批内窗口长度方差大</td><td>尾延迟由最长窗口支配，利用率下降</td><td>按窗口长度分桶调度，限制混批跨度</td></tr><tr><td>特征缓存/时间戳不一致</td><td>窗口错位、关键词截断</td><td>共享缓存加版本号，前端统一时钟</td></tr></tbody></table>\n<p>因此规模上限不由 ρ 单独决定，而由“回退率 × 回退成本 + 窗口方差 × 批效率损失”共同约束：回退到全量解码的请求虽少，却携带全量算力与带宽，一旦回退率随噪声环境上升，节省的 ρ 被迅速吃掉。工程判断是给裁剪调度设一个窗口方差阈值与回退率上限，超过即整体降级为全量批处理——把不确定性留给调度器，而不是留给召回率。</p>\n<h3 id=\"alg-asr-keyword-bifocal-sec-40\">四十 · 漏检链路的可观测化：从召回缺口到帧级归因</h3>\n<p>关键词聚焦 ASR 的失败不是单点崩溃，而是一条链：KWS 分支在噪声与口音下更易漏检，候选与时间戳缺失后调度器裁不出窗口，主 ASR 便对关键词帧走廉价路径，最终下游 NLU 收到的是残缺文本。诊断的第一原则是把这条链拆成可独立观测的三段——KWS 候选输出、裁剪窗口区间、主 ASR 实际精细解码的帧集合——并让三者在同一 utterance id 下对齐落盘。工程上以帧级覆盖率作为核心指标：设某请求真值关键词区间为 $[t_s, t_e]$，实际精细解码区间为 $[\\hat t_s, \\hat t_e]$，定义</p>\n<div class=\"formula\">$$\\text{cover} = \\frac{|[t_s,t_e] \\cap [\\hat t_s,\\hat t_e]|}{t_e - t_s},\\qquad \\text{miss} = \\mathbb{1}[\\text{cover} &lt; \\tau]$$</div>\n<p>其中 $\\tau$ 是判定漏检的覆盖阈值。cover 低于 $\\tau$ 的请求即进入漏检队列，按噪声类型、口音簇、KWS 分支量化档位分桶统计。代价上，这套埋点本身要花带宽：每请求多写一条候选与窗口记录，在高 QPS 下日志吞吐会成为瓶颈，因此只在 cover 异常或下游 NLU 置信度低时全量落盘，其余采样。具体例子：同一段带背景音乐的请求，KWS 输出候选时间戳比真值提前若干帧，裁剪窗口左边界截掉了关键词首音节，cover 落在阈值以下，帧级归因直接指向时间戳偏移而非模型召回不足——这两类故障的修复动作完全不同，前者调时间戳对齐，后者调 KWS 精度或阈值。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-41\">四十一 · 特征缓存不一致与窗口错位的静默故障</h3>\n<p>比漏检更隐蔽的是 KWS 与主 ASR 共享前端特征缓存不一致或时间戳偏移导致的裁剪窗口错位：KWS 判定命中，窗口也裁出来了，但窗口边界偏了，关键词被截断解码，输出文本看似合理却丢了前缀或后缀。这类故障在监控上不表现为召回下降，而表现为“解码成功但下游 NLU 意图置信度偏低”或“关键词文本长度分布左移”。诊断手段是双路校验：对同一批请求并行跑一次全量解码（仅抽样，比例受算力预算约束），比较聚焦路径与全量路径的关键词文本编辑距离，编辑距离超阈值的请求即判定为窗口错位嫌疑。代价明确——抽样全量解码直接吃掉本方法省下的算力，因此抽样率必须与 SLO 余量挂钩，在首包延迟吃紧时降到最低。机制上还应校验共享缓存的对齐契约：KWS 与主 ASR 必须消费同一份前端特征、同一帧率、同一时间基，任何一侧做了低帧率或低精度降采样，时间戳就必须重映射。具体例子：非关键词帧走低帧率路径以省带宽，若该路径的帧索引未与精细路径统一到同一时间基，窗口右边界会系统性偏移若干帧，故障表现为所有含长尾音的关键词被截断，且只在启用低帧率路径的实例上复现。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-42\">四十二 · OOM 与批抖动的耦合：裁剪窗口批的碎片化</h3>\n<p>主 ASR 按裁剪窗口批处理，而窗口长度随关键词时长波动，batch 内混合不同请求的裁剪窗口意味着批内序列长度高度不均。这带来两类耦合故障：其一，显存按批内最长窗口分配 KV cache 与激活，短窗口请求被迫陪跑长窗口的显存预算，长关键词请求一多就触发 OOM；其二，批构成抖动使每步解码的实际计算量在批间跳变，吞吐曲线出现锯齿，尾延迟被最长窗口拖拽。诊断上应监控批内窗口长度的分布（最大值、P99、方差）与每批实际占用显存，把 OOM 事件回溯到触发批的长度直方图。缓解机制是窗口长度分桶加令牌预算：调度器按窗口时长把请求分到不同桶，每桶独立组批，并以批内总帧数而非请求数作为组批上限。公式化地，设批内请求窗口长为 $l_i$，组批约束为</p>\n<div class=\"formula\">$$\\sum_i l_i \\le L_{\\max},\\qquad \\max_i l_i \\le l_{\\text{cap}}$$</div>\n<p>其中 $L_{\\max}$ 是帧预算、$l_{\\text{cap}}$ 是单窗口上限，超限请求单独成批或回退全量路径。代价是分桶降低批内混合度、增大批次数，小批量下 GPU 利用率下降，吞吐让位于稳定性。具体例子：一批混合了短命令词与长自由说片段的请求，最长窗口把显存推到上限，后续短请求排队等显存释放，首包延迟尖刺正是由此产生；分桶后短请求自成小批快速周转，长窗口请求单独承担显存峰值。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-43\">四十三 · 路由不均与场景切换的迟滞</h3>\n<p>流量构成决定收益：关键词与命令词占比高时 $\\rho$ 小、节省显著；自由听写场景 $\\rho$ 接近 1，裁剪收益消失，调度与拼接开销反使吞吐低于全量解码。失败模式是路由判定滞后——流量已从命令词转向自由听写，调度器仍按聚焦路径组批，结果是大量窗口接近整段 utterance，批碎片化叠加拼接开销，吞吐双输。诊断需要在线估计 $\\rho$：以 KWS 命中时长占 utterance 时长的滑动均值作为路由信号，同时监控聚焦路径与全量路径的单位请求成本比，当该比值越过 1 即触发路径切换。机制上应设置双阈值迟滞，避免在 $\\rho$ 临界点附近来回抖动导致批构成反复重组。代价是迟滞区间内的请求跑在次优路径上，短期吞吐受损换取长期稳定。具体例子：某实例的流量在短时间内从命令词密集切到长段听写，$\\rho$ 滑动均值持续抬升，越过上阈值后调度器把新请求全部导入全量解码路径，已有批不打断、自然排空，避免了中途重组批带来的尾延迟尖刺。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-44\">四十四 · 尾延迟尖刺的定位与回滚策略</h3>\n<p>尾延迟尖刺在聚焦路径上有三个典型来源：漏检回退到全量解码的兜底请求、窗口错位触发的重解码、以及批内最长窗口拖拽。兜底策略本身是稳定性技巧，但它把漏检请求的计算量瞬间放大到全量水平，若回退请求集中出现，P99 首包延迟会被这批请求主导。诊断上应把回退请求单独打标，统计其占批比例与到达的时间聚集性，区分“零星回退”与“系统性漏检引发的回退潮”。回滚策略分层：第一层是单请求级回退，漏检即走全量解码，保证召回；第二层是实例级降级，当回退比例越过阈值，该实例临时关闭聚焦路径、全部走全量解码，牺牲吞吐保 SLO；第三层是配置级回滚，把 KWS 阈值、窗口边界余量、量化档位回退到上一稳定版本。代价是实例级降级期间算力消耗回升到全量水平，容量规划必须为降级态预留余量，否则降级本身会引发 OOM。具体例子：KWS 分支采用更激进量化后召回下降，漏检回退请求在批中占比抬升，尾延迟尖刺与回退比例同步出现，此时正确的动作是把 KWS 量化档位回滚而非调主 ASR 精度——因为故障源在轻量分支而非精细路径。监控面板应把“回退比例”“批内窗口长度方差”“cover 分布”“路径成本比”四个信号并排，任何一个越界都指向明确的回滚层级，而不是笼统地重启实例。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-45\">四十五 · 关键词聚焦 ASR 的失效边界与回滚判据</h3>\n<p>这套方案真正的工程风险不在稳态吞吐，而在<b>漏检与错位</b>两类静默故障。KWS 分支输出的是关键词候选与时间戳，调度器据此裁剪主 ASR 的输入帧窗口；一旦 KWS 在噪声、口音或远场条件下漏掉一个关键词，主 ASR 根本不会对该区域做精细声学编码，下游 NLU 收到的是残缺文本，而系统指标上只表现为\"识别结果偏短\"，不会报错。更隐蔽的是时间戳偏移：KWS 与主 ASR 共享前端特征缓存，若两侧缓存版本不一致或帧对齐差一帧，裁剪窗口就会把关键词首尾截断，解码出半个词。这两类故障都不触发异常，只能靠<b>端到端召回率</b>而非分支内部指标来暴露。诊断上应把 KWS 候选时间戳与主 ASR 精细窗口做逐条比对，统计\"KWS 命中但窗口未覆盖\"的比例，作为独立的错位率指标上报；同时以固定的小比例流量强制走全量解码路径做影子对照，用两路文本的编辑距离分布作为召回漂移的探针，而不是等用户投诉。</p>\n<p>收益的边界由关键词时长占比 ρ 直接决定。裁剪后的计算量近似为 <span class=\"formula\">$$\\mathrm{FLOPs}_{\\mathrm{focus}} \\approx \\rho\\cdot \\mathrm{FLOPs}_{\\mathrm{full}}$$</span>，ρ 越小节省越多；但自由听写场景 ρ 接近 1，主 ASR 仍要覆盖几乎全部帧，此时裁剪不但不省算力，反而额外付出 KWS 前向、窗口调度与结果拼接三份开销，吞吐会低于全量解码。因此启用条件必须写成流量构成的函数而非全局开关：按请求类型（命令词、关键词查询、自由听写）分别统计 ρ 的分布，只有当某类流量的 ρ 中位数显著低于切换阈值时才走聚焦路径，其余请求在入口处直接路由到全量解码。这个路由判断本身要廉价——用请求来源、唤醒词上下文或首帧能量等轻量特征做预判，避免为判断而先跑一遍 KWS。切换逻辑的代价是双路径常驻：两套解码图、两份量化配置（KWS 可用更激进精度，主 ASR 保留精细路径）同时占显存，容量规划要按峰值而非均值留余量。</p>\n<p>裁剪窗口批处理还会引入<b>批抖动</b>与尾延迟尖刺。主 ASR 按窗口调度，不同请求的窗口长度差异很大，连续批处理里长短窗口混排会让 batch 的有效 token 数剧烈波动，长窗口请求被短请求反复插入而推迟，首包延迟的 P99 被拉高。缓解手段是给窗口长度分桶、限制单批内窗口长度的极差，并对超长窗口单独走低优先级队列；代价是分桶降低了批的填充率，吞吐略降换取尾延迟可控。监控上应把\"窗口长度分布\"\"单批极差\"\"KWS 到主 ASR 的排队时延\"作为一等指标，与首包延迟 P50/P99 联动看，才能区分是算力不足还是调度不均。OOM 风险则来自共享前端特征缓存的驻留策略：流式场景下缓存随会话增长，若按会话粒度不设上限，长会话叠加高并发会挤爆显存；应给缓存设硬上限并按 LRU 淘汰，淘汰时同步失效对应窗口的上下文状态，否则会出现窗口错位。回滚判据要提前写死：当影子对照的召回下降超过预设带宽、或错位率突增、或 P99 首包延迟越过 SLO，自动把该类流量切回全量解码路径，并保留 KWS 分支仅作观测，待根因（缓存版本、时间戳对齐、噪声鲁棒性）修复后再灰度放量。</p>\n<table class=\"mini\"><thead><tr><th>故障</th><th>可观测信号</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>KWS 漏检</td><td>影子对照编辑距离上升</td><td>召回下降，无报错</td><td>该类流量回退全量</td></tr><tr><td>窗口错位</td><td>命中未覆盖率上升</td><td>关键词截断解码</td><td>校验缓存版本与帧对齐</td></tr><tr><td>ρ 偏高</td><td>裁剪收益转负</td><td>吞吐低于全量</td><td>入口路由切全量路径</td></tr><tr><td>批抖动</td><td>单批窗口极差大、P99 抬升</td><td>填充率下降</td><td>长度分桶、长窗隔离</td></tr></tbody></table>\n<h3 id=\"alg-asr-keyword-bifocal-sec-46\">四十六 · 决策维度：把选型压缩成三个可测量</h3>\n<p>与相邻算法对照时，不要按“模型结构”选，而按三个可测量的量选：关键词时长占比 ρ、KWS 分支的召回率与误触发率、裁剪窗口的调度开销。这三个量直接决定 bifocal 路径是否优于全量解码、是否优于流式编解码器分块推理、是否优于非自回归时长预测批推理。ρ 是唯一进入主公式的量：</p>\n<div class=\"formula\">$$\\text{FLOPs}_{\\text{bifocal}} \\approx \\text{FLOPs}_{\\text{KWS}} + \\rho \\cdot \\text{FLOPs}_{\\text{ASR}},\\quad \\rho = \\frac{T_{\\text{kw}}}{T_{\\text{utt}}} \\ll 1$$</div>\n<p>工程上要盯的不是理论 FLOPs，而是裁剪窗口批处理后的实际 SM 占用：当 ρ 小但窗口长度离散（不同请求的关键词时长差异大），批内窗口对齐会引入 padding，实际节省低于公式预测。因此决策表的第一列应是“窗口长度方差”，而非单纯的 ρ。第二个量是 KWS 召回率：漏检一次，该请求就退回全量解码兜底，兜底率乘以全量成本构成隐性开销。第三个量是调度开销：裁剪、拼接、缓存一致性检查在每帧上的固定成本，在 ρ 接近 1 时反超节省。</p>\n<p>具体例子：一条 6 秒的助手请求，关键词窗口 0.4 秒，ρ≈0.07，主 ASR 精细解码只覆盖约 7% 的帧；若同一 batch 内混入一条 5 秒自由听写请求（ρ≈1），批内窗口对齐会把短窗口请求的调度收益吃掉，此时应把两类请求分桶而非混批。这个判断不需要实验数字，只需要看流量构成里 ρ 的分布。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-47\">四十七 · 决策表：五条路径的适用条件</h3>\n<p>把同族候选压成一张表，每行给出“选它的条件”和“不选它的信号”。表中不重复各算法机制，只给判据。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>路径</th><th>选它的条件</th><th>不选它的信号</th><th>主要代价</th></tr>\n</thead>\n<tbody>\n<tr><td>关键词聚焦 bifocal</td><td>命令词/关键词请求占多数，ρ 低且窗口长度方差小，KWS 召回率可兜底</td><td>自由听写占比高，或噪声/口音使漏检率上升</td><td>漏检召回损失、裁剪调度固定开销</td></tr>\n<tr><td>全量 ASR 解码</td><td>ρ 接近 1，或对召回零容忍（医疗、法律转写）</td><td>算力与显存带宽成为瓶颈</td><td>对所有帧一视同仁，带宽与算力浪费</td></tr>\n<tr><td>流式编解码器分块推理</td><td>需要低首包延迟的连续流，块边界可预定义</td><td>关键词位置不可预知、需按内容裁剪</td><td>块间上下文重复计算</td></tr>\n<tr><td>非自回归时长预测批推理</td><td>离线或准离线批量转写，吞吐优先于首包</td><td>交互式助手，首包 SLO 紧</td><td>时长预测误差传导到对齐</td></tr>\n<tr><td>低比特量化边缘推理</td><td>端侧部署、功耗与显存受限</td><td>服务端带宽充裕、精度敏感</td><td>量化误差在关键词边界放大</td></tr>\n</tbody>\n</table>\n<p>表的使用方式是排除法：先看 ρ 分布，ρ 高的流量直接排除 bifocal；再看 SLO 是首包还是吞吐，首包紧的排除非自回归批推理；最后看部署位置，端侧才考虑低比特量化。剩下的候选再用 KWS 召回率与调度开销做二次筛选。注意 bifocal 与流式分块不是互斥的：分块解决“何时出结果”，bifocal 解决“对哪些帧精细算”，二者可叠加，但叠加后调度器要同时维护块边界与关键词窗口两套索引，缓存一致性检查成本上升。</p>\n<p>具体例子：一个车载语音助手，80% 请求是“导航到某地”“调高音量”这类命令词，ρ 中位数远小于 1，窗口长度集中在短命令，选 bifocal；其中 20% 是自由口述目的地，按 ρ 分桶走全量解码，避免混批导致的窗口对齐浪费。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-48\">四十八 · 适用条件的量化边界</h3>\n<p>把“适用”写成不等式，而不是形容词。bifocal 相对全量解码的净收益近似为：</p>\n<div class=\"formula\">$$\\text{Gain} \\approx (1-\\rho)\\cdot C_{\\text{ASR}} - C_{\\text{KWS}} - C_{\\text{sched}} - \\lambda_{\\text{miss}}\\cdot C_{\\text{ASR}}$$</div>\n<p>其中 C 为单请求成本，λ_miss 为漏检后回退全量的比例。收益为正的条件是 ρ 足够小、KWS 成本远低于主 ASR、调度开销可摊薄、漏检率可控。这条不等式给出三条硬边界：其一，ρ 上升到使 (1−ρ) 项缩小时，调度开销成为主导，收益转负；其二，KWS 分支若不能常驻流式前端而需单独加载，其固定成本会吃掉小 ρ 的节省；其三，漏检率随噪声与口音上升，λ_miss 增大时兜底全量解码的比例上升，等效 ρ 被抬高。</p>\n<p>系统代价要按分支拆开看：KWS 分支常驻带来持续的前端算力与显存占用，主 ASR 的裁剪窗口批处理降低的是峰值算力与显存带宽，二者不是同一本账。首包延迟由 KWS 定位加窗口裁剪加主 ASR 精细解码三段构成，KWS 轻量使前两段短，但窗口裁剪若需等待时间戳稳定，会引入额外等待。吞吐侧，裁剪窗口批处理让 batch 内不同请求的窗口混合，提升 SM 利用率，但窗口长度方差大时 padding 拉低有效吞吐。</p>\n<p>具体例子：同一服务里，命令词请求的窗口约数百毫秒、自由听写请求覆盖整段音频；若把两者混批，padding 使短窗口请求的有效算力占比下降，吞吐反而不如按 ρ 分桶后各自批处理。分桶的代价是队列延迟，需要在 SLO 内用最大等待时间兜住。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-49\">四十九 · 与全量解码的切换逻辑</h3>\n<p>切换不是二选一，而是按请求级 ρ 估计做路由。路由信号来自 KWS 分支自身：关键词候选数量、候选时间戳的置信度、以及前端特征缓存中非关键词段的能量分布。伪代码思路如下：</p>\n<ul>\n<li>每帧入 KWS 分支，累计候选与时间戳，维护一个滑动窗口的 ρ 估计；</li>\n<li>若 ρ 估计低于阈值且候选置信度高于阈值，走裁剪窗口路径，主 ASR 只编码窗口帧；</li>\n<li>若候选置信度低于阈值或 ρ 估计越过阈值，标记该请求回退全量解码，已解码的窗口结果可复用；</li>\n<li>非关键词帧走低精度/低帧率路径，仅保留上下文状态供窗口解码拼接；</li>\n<li>拼接后送下游 NLU，同时把漏检标记回传，用于后续路由阈值调整。</li>\n</ul>\n<p>切换的代价在状态一致性：回退全量解码时，已走的低精度路径留下的上下文状态与精细路径不同，拼接处可能出现声学特征不连续。工程上要么在窗口边界保留一段重叠帧做精细重算，要么让低精度路径输出与精细路径同维度的状态表示。前者增加算力，后者增加实现复杂度。另一个代价是路由抖动：ρ 估计在请求早期不稳定，过早路由会导致频繁回退，过晚路由则失去节省窗口。用最小观测时长加迟滞阈值抑制抖动，代价是首包延迟增加。</p>\n<p>具体例子：一条请求开头几帧安静，ρ 估计偏低，路由到裁剪路径；随后出现连续语音，ρ 估计上升触发回退，此时已解码的窗口结果保留，仅对剩余帧补全量解码，避免整条重算。这个“部分复用”策略是切换逻辑的关键，否则回退成本等于全量加已做工作。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-50\">五十 · 与量化、分块、批调度的组合判断</h3>\n<p>组合判断的原则是：只叠加代价不重叠的优化。bifocal 降的是“对哪些帧精细算”，量化降的是“每帧算多贵”，分块降的是“何时能出结果”，批调度降的是“批内利用率”。四者代价来源不同，可叠加，但叠加顺序影响实现复杂度。</p>\n<p>与低比特量化的组合：KWS 分支可用更激进精度，主 ASR 保留精细路径，量化按分支分别配置。代价是两套量化参数带来两套反量化路径，显存带宽在分支切换处出现尖峰；若共享前端特征缓存，缓存本身的精度要与两个分支都兼容，否则缓存命中反而引入精度损失。与流式分块推理的组合：分块给出固定的块边界，bifocal 在块内再裁剪窗口，调度器需同时维护两套索引，缓存一致性检查在块边界与窗口边界双重触发，固定开销上升。与批调度的组合：按 ρ 分桶批处理是收益最大的组合，桶内窗口长度接近，padding 小；代价是队列延迟与桶间负载不均，需要按 SLO 设最大等待时间并在桶空时借用其他桶的请求。</p>\n<p>系统代价的合并账：bifocal 省的是主 ASR 的峰值算力与显存带宽，量化省的是每帧的带宽与功耗，分块省的是首包等待，批调度省的是 SM 空闲。四者叠加时，瓶颈会从算力转向调度与缓存一致性检查的固定开销，此时应减少叠加层数而非继续加优化。具体例子：端侧助手同时用 bifocal、低比特量化与分块，KWS 常驻占用固定显存，主 ASR 窗口解码的峰值显存下降，但两套量化参数与双索引调度使每帧固定开销上升；在 ρ 很低的命令词场景仍有净收益，在 ρ 上升时固定开销先于算力成为瓶颈，应退回单层优化。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-51\">五十一 · 选型失败的反向信号</h3>\n<p>反向信号比正向指标更早暴露选型错误。第一类信号是兜底率：漏检回退全量解码的比例持续上升，说明 KWS 召回率在该流量构成下不足，bifocal 的等效 ρ 被抬高，应降低 bifocal 流量占比或换更稳的 KWS。第二类信号是批内有效算力占比：窗口长度方差大导致 padding 上升，吞吐低于全量解码，说明应按 ρ 分桶而非混批。第三类信号是缓存一致性告警：KWS 与主 ASR 前端特征缓存不一致或时间戳偏移，导致裁剪窗口错位、关键词被截断解码，这类失败在拼接处表现为文本缺字，需在窗口边界加重叠帧校验。第四类信号是调度开销占比：ρ 接近 1 时裁剪与拼接开销反超节省，吞吐低于全量解码，此时应直接切回全量路径，而不是继续调调度参数。</p>\n<p>这些信号共同指向一个工程判断：bifocal 的适用性由流量构成决定，而非由模型能力决定。流量构成漂移（例如从命令词为主转向自由口述为主）时，路由阈值与分桶策略要随之调整，否则召回与吞吐双输。选型的最终落点是“按 ρ 分布分桶加请求级路由加漏检兜底”这一套组合，而不是在单条路径上追求极限优化。</p>\n\n<h3 id=\"alg-asr-keyword-bifocal-sec-52\">五十二 · 关键词聚焦 ASR 的选型边界：与全量解码、级联 KWS-ASR 的分野</h3>\n<p>把关键词聚焦 ASR 放进同族算法谱系里，真正的分水岭不是\"是否用 KWS\"，而是\"主 ASR 的算力是否随关键词稀疏度缩放\"。全量解码对所有帧一视同仁，代价是 <span class=\"formula\">$$\\text{FLOPs}_{\\text{full}} = T_{\\text{utt}} \\cdot c_{\\text{frame}}$$</span>，与请求内容无关；级联 KWS-ASR 则是两套独立模型串行，KWS 命中后仍把整段音频送主 ASR，节省只体现在\"未命中即不唤醒\"这一跳；而本方案用 <span class=\"formula\">$$\\text{FLOPs}_{\\text{bifocal}} \\approx \\text{FLOPs}_{\\text{KWS}} + \\rho \\cdot \\text{FLOPs}_{\\text{ASR}}$$</span> 把主模型算力压到关键词时长占比 <span class=\"formula\">$$\\rho = T_{\\text{kw}}/T_{\\text{utt}} \\ll 1$$</span>。三者选型的判据因此落在流量配方上：关键词稀疏度决定 <span class=\"formula\">$$\\rho$$</span>，而 <span class=\"formula\">$$\\rho$$</span> 直接决定裁剪调度开销能否被摊薄。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>适用条件</th><th>失效条件</th><th>主要系统代价</th></tr></thead><tbody><tr><td>全量 ASR</td><td>自由听写、关键词密集、<span class=\"formula\">$$\\rho \\to 1$$</span></td><td>助手流量下算力与带宽浪费</td><td>首包延迟受整段编码约束</td></tr><tr><td>级联 KWS-ASR</td><td>唤醒词/单命令，命中率低</td><td>多关键词长句、需上下文消歧</td><td>两模型常驻显存，前端特征重复提取</td></tr><tr><td>关键词聚焦 ASR</td><td>关键词稀疏、命令词为主、SLO 以首包延迟为主</td><td>KWS 漏检、噪声口音、<span class=\"formula\">$$\\rho$$</span> 高</td><td>裁剪窗口调度与拼接开销、漏检兜底回退</td></tr></tbody></table>\n<p>边界条件必须写进调度器而非靠人工切换。KWS 漏检在噪声与口音下更易发生，一旦漏检，主 ASR 从未对该窗口做精细解码，召回率直接下降，且下游 NLU 拿到的是残缺文本——这类错误无法靠解码器置信度补救。工程上的兜底是设置漏检回退：当 KWS 候选为空而能量/端点检测显示存在语音活动时，强制走全量解码路径，代价是这条请求的延迟退回全量水平，但避免了静默丢词。另一个隐性失效是时间戳偏移：KWS 与主 ASR 若前端特征缓存不一致，裁剪窗口会错位，关键词被截断解码，表现为\"识别出半个词\"。共享前端特征缓存不只是省一次特征提取的带宽，更是保证两分支时间轴对齐的前提。</p>\n<p>系统代价的另一面是批处理形态的改变。全量解码可按 utterance 长度做连续批处理，而裁剪窗口长度不一，调度器要把不同请求的关键词窗口混批，窗口过短时单批有效算力被拉低，窗口拼接又引入额外拷贝。因此本方案的吞吐收益并非无条件成立：当 <span class=\"formula\">$$\\rho$$</span> 接近 1（自由听写），裁剪收益消失，调度与拼接开销反使吞吐低于全量解码，此时应退回全量路径。量化配置也需按分支分开：KWS 可承受更激进的低精度以常驻流式前端压低首包延迟，主 ASR 的精细路径则保留较高精度以守住关键词识别质量；非关键词帧走低精度或低帧率路径只为保留上下文状态，省的是显存带宽而非算力。选型的最终判断是：以关键词/命令词为主、<span class=\"formula\">$$\\rho$$</span> 小且 KWS 召回率可测可控的助手流量，用本方案；自由听写或关键词密集场景，直接走全量解码，不要用裁剪调度去赌召回。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2021 · 语音识别与音频理解推理</td></tr><tr><td>解决什么</td><td>语音助手中 ASR 全量解码计算量大，而多数请求只需识别少量关键词/命令词，全模型推理浪费算力与显存带宽。</td></tr><tr><td>一句话机制</td><td>先用轻量关键词检测（KWS）分支定位关键词区域，再让主 ASR 模型只对关键词附近帧做精细解码，其余帧走廉价路径或跳过。</td></tr><tr><td>代价与失效</td><td>KWS 漏检会导致关键词未被精细解码，召回率下降；自由听写场景关键词占比高时收益消失，需按场景切换全量解码</td></tr><tr><td>后继</td><td>编解码器 LM 流式预填解码</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-asr-keyword-bifocal · 共 8 个片段</p>\n";break;}}})();
